import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { Client, Loan, Transaction, LoanStatus } from '../types';

interface StoreContextType {
  clients: Client[];
  loans: Loan[];
  transactions: Transaction[];
  addClient: (client: Client) => void;
  createLoan: (loanData: Omit<Loan, 'id' | 'status' | 'remainingBalance' | 'totalToPay'>) => void;
  registerPayment: (loanId: string, amount: number, note: string) => void;
  getFinancialStats: () => { balance: number; incomeToday: number; expenseToday: number };
}

const StoreContext = createContext<StoreContextType | undefined>(undefined);

// Initial Mock Data to populate the app
const initialClients: Client[] = [
  { id: '1', name: 'Ana Martínez', cedula: '001-0020030-4', phone: '809-555-0101', address: 'Calle 1, Zona Norte', creditScore: 95, status: 'Activo', joinedDate: '2023-01-15' },
  { id: '2', name: 'Roberto Gómez', cedula: '001-0040050-6', phone: '809-555-0102', address: 'Av. 27 de Febrero', creditScore: 60, status: 'Activo', joinedDate: '2023-03-20' },
  { id: '3', name: 'Carla Ruiz', cedula: '402-0090080-7', phone: '809-555-0103', address: 'Los Prados', creditScore: 88, status: 'Activo', joinedDate: '2023-06-10' },
];

const initialLoans: Loan[] = [
  { 
    id: 'LN-1001', clientId: '1', clientName: 'Ana Martínez', amount: 10000, interestRate: 10, durationWeeks: 12, frequency: 'Semanal',
    startDate: '2023-10-01', status: LoanStatus.ACTIVE, totalToPay: 11000, remainingBalance: 5000, nextPaymentDate: '2023-10-15'
  },
  { 
    id: 'LN-1002', clientId: '2', clientName: 'Roberto Gómez', amount: 5000, interestRate: 20, durationWeeks: 8, frequency: 'Semanal',
    startDate: '2023-09-15', status: LoanStatus.OVERDUE, totalToPay: 6000, remainingBalance: 3000, nextPaymentDate: '2023-10-01'
  }
];

const initialTransactions: Transaction[] = [
  { id: 'TRX-001', type: 'Gasto', category: 'Desembolso', amount: 10000, date: '2023-10-01', description: 'Desembolso LN-1001', referenceId: 'LN-1001' },
  { id: 'TRX-002', type: 'Ingreso', category: 'Pago Préstamo', amount: 2000, date: '2023-10-08', description: 'Cuota LN-1001', referenceId: 'LN-1001' },
  { id: 'TRX-003', type: 'Ingreso', category: 'Capital', amount: 50000, date: '2023-09-01', description: 'Capital Inicial' },
];

export const StoreProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [clients, setClients] = useState<Client[]>(initialClients);
  const [loans, setLoans] = useState<Loan[]>(initialLoans);
  const [transactions, setTransactions] = useState<Transaction[]>(initialTransactions);

  const addClient = (client: Client) => {
    setClients(prev => [client, ...prev]);
  };

  const createLoan = (loanData: Omit<Loan, 'id' | 'status' | 'remainingBalance' | 'totalToPay'>) => {
    const totalInterest = loanData.amount * (loanData.interestRate / 100);
    const totalToPay = loanData.amount + totalInterest;

    const newLoan: Loan = {
      ...loanData,
      id: `LN-${Math.floor(1000 + Math.random() * 9000)}`,
      status: LoanStatus.ACTIVE,
      totalToPay,
      remainingBalance: totalToPay,
    };

    setLoans(prev => [newLoan, ...prev]);

    // Record Disbursal Transaction (Expense)
    const transaction: Transaction = {
      id: `TRX-${Math.floor(Date.now() / 1000)}`,
      type: 'Gasto',
      category: 'Desembolso',
      amount: loanData.amount,
      date: new Date().toISOString().split('T')[0],
      description: `Desembolso préstamo para ${loanData.clientName}`,
      referenceId: newLoan.id
    };
    setTransactions(prev => [transaction, ...prev]);
  };

  const registerPayment = (loanId: string, amount: number, note: string) => {
    // Update Loan Balance
    setLoans(prevLoans => prevLoans.map(loan => {
      if (loan.id === loanId) {
        const newBalance = Math.max(0, loan.remainingBalance - amount);
        const newStatus = newBalance === 0 ? LoanStatus.PAID : LoanStatus.ACTIVE;
        return { ...loan, remainingBalance: newBalance, status: newStatus };
      }
      return loan;
    }));

    // Record Payment Transaction (Income)
    const loan = loans.find(l => l.id === loanId);
    const transaction: Transaction = {
      id: `TRX-${Math.floor(Date.now() / 1000)}`,
      type: 'Ingreso',
      category: 'Pago Préstamo',
      amount: amount,
      date: new Date().toISOString().split('T')[0],
      description: `Pago: ${note} - ${loan?.clientName}`,
      referenceId: loanId
    };
    setTransactions(prev => [transaction, ...prev]);
  };

  const getFinancialStats = () => {
    const today = new Date().toISOString().split('T')[0];

    const balance = transactions.reduce((acc, curr) => {
      return curr.type === 'Ingreso' ? acc + curr.amount : acc - curr.amount;
    }, 0);

    const incomeToday = transactions
      .filter(t => t.date === today && t.type === 'Ingreso')
      .reduce((sum, t) => sum + t.amount, 0);

    const expenseToday = transactions
      .filter(t => t.date === today && t.type === 'Gasto')
      .reduce((sum, t) => sum + t.amount, 0);

    return { balance, incomeToday, expenseToday };
  };

  return (
    <StoreContext.Provider value={{ clients, loans, transactions, addClient, createLoan, registerPayment, getFinancialStats }}>
      {children}
    </StoreContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(StoreContext);
  if (context === undefined) {
    throw new Error('useStore must be used within a StoreProvider');
  }
  return context;
};

