            {client.name.charAt(0)}
        </div>
        <div className="flex-1 text-center md:text-left">
            <h1 className="text-2xl font-bold text-slate-900">{client.name}</h1>
            <p className="text-slate-500 font-medium">ID: {client.id} • {client.cedula}</p>
            <div className="flex flex-wrap gap-4 mt-4 justify-center md:justify-start">
                 <div className="flex items-center gap-2 text-slate-600 text-sm bg-slate-50 px-3 py-1.5 rounded-lg border border-slate-200">
                    <Phone className="w-4 h-4 text-indigo-500" />
                    {client.phone}
                 </div>
                 <div className="flex items-center gap-2 text-slate-600 text-sm bg-slate-50 px-3 py-1.5 rounded-lg border border-slate-200">
                    <MapPin className="w-4 h-4 text-indigo-500" />
                    {client.address}
                 </div>
                 <div className={`px-3 py-1.5 rounded-lg text-sm font-bold border ${client.status === 'Activo' ? 'bg-emerald-50 border-emerald-200 text-emerald-700' : 'bg-rose-50 border-rose-200 text-rose-700'}`}>
                    {client.status}
                 </div>
            </div>
        </div>
        <div className="text-center md:text-right border-t md:border-t-0 md:border-l border-slate-100 pt-4 md:pt-0 md:pl-6 w-full md:w-auto">
