                                value={newBank.holderName} onChange={e => setNewBank({...newBank, holderName: e.target.value})} 
                            />
                            <select 
                                className="p-2 border rounded-lg"
                                value={newBank.accountType} onChange={e => setNewBank({...newBank, accountType: e.target.value as any})}
                            >
                                <option value="Ahorro">Ahorro</option>
                                <option value="Corriente">Corriente</option>
                            </select>
                            <div className="md:col-span-2 flex gap-2 justify-end mt-2">
                                <button type="button" onClick={() => setShowBankForm(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-200 rounded-lg">Cancelar</button>
                                <button type="submit" className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 font-medium">Guardar Cuenta</button>
                            </div>
                        </form>
                    </div>
                )}
            </div>
        )}

        {/* Notes */}
        {activeTab === 'notes' && (
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 animate-fade-in">
                <div className="md:col-span-2 space-y-4">
                    {myNotes.length === 0 ? (
                        <div className="text-center py-10 text-slate-400 bg-slate-50 rounded-xl border border-dashed border-slate-200">
                            No hay notas registradas para este cliente.
                        </div>
                    ) : (
                        myNotes.map(note => (
                            <div key={note.id} className="bg-yellow-50 p-4 rounded-xl border border-yellow-100 shadow-sm relative">
                                <p className="text-slate-800 whitespace-pre-line">{note.content}</p>
                                <div className="flex justify-between items-center mt-3 pt-3 border-t border-yellow-200/50">
                                    <span className="text-xs font-bold text-yellow-700">{note.createdBy}</span>
                                    <span className="text-xs text-yellow-600">{note.date}</span>
                                </div>
                            </div>
                        ))
                    )}
                </div>
                <div>
                    <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100 sticky top-4">
                        <h4 className="font-bold text-slate-800 mb-2">Agregar Nota</h4>
                        <textarea 
                            className="w-full border border-slate-200 rounded-lg p-3 text-sm focus:ring-2 focus:ring-indigo-500 outline-none resize-none h-32"
                            placeholder="Escribe una nota sobre el cliente..."
                            value={newNote}
                            onChange={(e) => setNewNote(e.target.value)}
                        ></textarea>
                        <button 
                            onClick={handleAddNote}
                            disabled={!newNote.trim()}
                            className="w-full mt-3 bg-indigo-600 text-white py-2 rounded-lg font-medium hover:bg-indigo-700 disabled:opacity-50"
                        >
                            Guardar Nota
                        </button>
                    </div>
                </div>
            </div>
        )}

      </div>
    </div>
  );
};

export default ClientDetail;

import React, { useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { 
  User, Phone, MapPin, ArrowLeft, Banknote, CalendarClock, 
  StickyNote, Landmark, Plus, Trash2, Edit, X, FileText, Printer, CheckCircle
} from 'lucide-react';
import { useStore } from '../context/StoreContext';
import { LoanStatus, BankAccount, Client, Loan, Transaction } from '../types';

const ClientDetail: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { clients, loans, transactions, bankAccounts, clientNotes, addBankAccount, removeBankAccount, addClientNote, updateClient } = useStore();

  const client = clients.find(c => c.id === id);
  const [activeTab, setActiveTab] = useState<'general' | 'loans' | 'payments' | 'banks' | 'notes'>('general');

  // State for new Bank Account
  const [newBank, setNewBank] = useState<Partial<BankAccount>>({ bankName: '', accountNumber: '', accountType: 'Ahorro', holderName: '' });
  const [showBankForm, setShowBankForm] = useState(false);

  // State for new Note
  const [newNote, setNewNote] = useState('');

  // State for Edit Client Modal
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [editFormData, setEditFormData] = useState<Client | null>(null);

  // State for Modals (Contract & Receipt)
  const [viewLoan, setViewLoan] = useState<Loan | null>(null);
  const [viewReceipt, setViewReceipt] = useState<Transaction | null>(null);

  if (!client) {
    return <div className="p-8 text-center text-slate-500">Cliente no encontrado.</div>;
  }

  // Filter Data for this Client
  const clientLoans = loans.filter(l => l.clientId === client.id);
  const clientTransactions = transactions.filter(t => 
    t.referenceId && clientLoans.some(l => l.id === t.referenceId)
  );
  const clientBanks = bankAccounts.filter(b => b.clientId === client.id);
  const myNotes = clientNotes.filter(n => n.clientId === client.id);

  const activeLoans = clientLoans.filter(l => l.status === LoanStatus.ACTIVE || l.status === LoanStatus.OVERDUE);
  const totalDebt = activeLoans.reduce((sum, l) => sum + l.remainingBalance, 0);

  const handleAddBank = (e: React.FormEvent) => {
    e.preventDefault();
    if(newBank.bankName && newBank.accountNumber) {
        addBankAccount({
            ...newBank as BankAccount,
            id: Date.now().toString(),
            clientId: client.id
        });
        setNewBank({ bankName: '', accountNumber: '', accountType: 'Ahorro', holderName: '' });
        setShowBankForm(false);
    }
  };

  const handleAddNote = () => {
    if(!newNote.trim()) return;
    addClientNote({
        id: Date.now().toString(),
        clientId: client.id,
        content: newNote,
        date: new Date().toISOString().split('T')[0],
        createdBy: 'Admin'
    });
    setNewNote('');
  };

  const handleEditClick = () => {
      setEditFormData({ ...client });
      setIsEditModalOpen(true);
  };

  const handleUpdateClient = (e: React.FormEvent) => {
      e.preventDefault();
      if(editFormData) {
          updateClient(editFormData);
          setIsEditModalOpen(false);
      }
  };

  return (
    <div className="max-w-6xl mx-auto space-y-6 animate-fade-in pb-10">
      {/* Header */}
      <div className="flex items-center gap-4 mb-2">
        <button onClick={() => navigate('/clientes')} className="p-2 hover:bg-slate-200 rounded-full transition-colors text-slate-600">
            <ArrowLeft className="w-6 h-6" />
        </button>
        <h2 className="text-2xl font-bold text-slate-800">Detalles del Cliente</h2>
      </div>

      {/* Profile Summary Card */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-100 p-6 flex flex-col md:flex-row items-center md:items-start gap-6 relative">
        <button 
            onClick={handleEditClick}
            className="absolute top-4 right-4 p-2 text-slate-400 hover:text-indigo-600 hover:bg-slate-50 rounded-lg transition-colors"
            title="Editar Información"
        >
            <Edit className="w-5 h-5" />
        </button>

        <div className="w-24 h-24 rounded-full bg-indigo-100 text-indigo-600 flex items-center justify-center font-bold text-3xl">
            {client.name.charAt(0)}
        </div>
        <div className="flex-1 text-center md:text-left">
            <h1 className="text-2xl font-bold text-slate-900">{client.name}</h1>
            <p className="text-slate-500 font-medium">ID: {client.id} • {client.cedula}</p>
            <div className="flex flex-wrap gap-4 mt-4 justify-center md:justify-start">
                 <div className="flex items-center gap-2 text-slate-600 text-sm bg-slate-50 px-3 py-1.5 rounded-lg border border-slate-200">
                    <Phone className="w-4 h-4 text-indigo-500" />
                    {client.phone}
                 </div>
                 <div className="flex items-center gap-2 text-slate-600 text-sm bg-slate-50 px-3 py-1.5 rounded-lg border border-slate-200">
                    <MapPin className="w-4 h-4 text-indigo-500" />
                    {client.address}
                 </div>
                 <div className={`px-3 py-1.5 rounded-lg text-sm font-bold border ${client.status === 'Activo' ? 'bg-emerald-50 border-emerald-200 text-emerald-700' : 'bg-rose-50 border-rose-200 text-rose-700'}`}>
