             <p className="text-sm text-slate-500">Deuda Total Activa</p>
             <p className="text-3xl font-bold text-rose-600">${totalDebt.toLocaleString()}</p>
             <p className="text-xs text-slate-400 mt-1">Score: {client.creditScore} pts</p>
        </div>
      </div>

