      <div className="flex overflow-x-auto gap-2 border-b border-slate-200 pb-1 scrollbar-hide">
        {[
            { id: 'general', label: 'Datos Generales', icon: User },
            { id: 'loans', label: 'Préstamos Asignados', icon: Banknote },
            { id: 'payments', label: 'Recibos / Pagos', icon: CalendarClock },
            { id: 'banks', label: 'Bancos', icon: Landmark },
