                            <div><p className="text-xs text-slate-400">Nombre</p><p className="font-medium">{client.name}</p></div>
                            <div><p className="text-xs text-slate-400">Cédula</p><p className="font-medium">{client.cedula}</p></div>
                            <div><p className="text-xs text-slate-400">Sexo</p><p className="font-medium">{client.sex}</p></div>
                            <div><p className="text-xs text-slate-400">Ocupación</p><p className="font-medium">{client.occupation}</p></div>
                            <div><p className="text-xs text-slate-400">Fecha Ingreso</p><p className="font-medium">{client.joinedDate}</p></div>
                        </div>
                    </div>
                </div>
                <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
                    <h3 className="font-bold text-lg text-slate-800 mb-4 border-b pb-2">Información de Contacto</h3>
                    <div className="space-y-4">
                        <div><p className="text-xs text-slate-400">Celular / WhatsApp</p><p className="font-medium text-lg text-indigo-600">{client.phone}</p></div>
                        <div><p className="text-xs text-slate-400">Teléfono Casa</p><p className="font-medium">{client.phoneHome || 'N/A'}</p></div>
                        <div><p className="text-xs text-slate-400">Dirección</p><p className="font-medium">{client.address}</p></div>
                    </div>
                </div>
                <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
                    <h3 className="font-bold text-lg text-slate-800 mb-4 border-b pb-2">Datos Financieros</h3>
                    <div className="space-y-4">
                         <div><p className="text-xs text-slate-400">Ingresos Mensuales</p><p className="font-medium text-emerald-600">${client.income?.toLocaleString()}</p></div>
                         <div><p className="text-xs text-slate-400">Score Crediticio</p><div className="flex items-center gap-2"><div className="w-24 h-2 rounded-full bg-slate-100"><div style={{width: `${client.creditScore}%`}} className="h-full bg-indigo-500 rounded-full"></div></div><span className="font-bold">{client.creditScore}</span></div></div>
                    </div>
                </div>
            </div>
        )}

        {/* Loans */}
        {activeTab === 'loans' && (
            <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden animate-fade-in">
