                                            <FileText className="w-4 h-4" />
                                            <span className="text-xs underline">Ver</span>
                                        </button>
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
            </div>
        )}

        {/* Payments / Receipts */}
        {activeTab === 'payments' && (
            <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden animate-fade-in">
                <table className="w-full text-left">
