                            <th className="px-6 py-4 text-center">Recibo</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {clientTransactions.length === 0 ? (
                            <tr><td colSpan={5} className="text-center py-8 text-slate-400">No hay transacciones registradas.</td></tr>
                        ) : (
                            clientTransactions.map(trx => (
                                <tr key={trx.id} className="hover:bg-slate-50">
                                    <td className="px-6 py-4 font-mono text-slate-500">{trx.referenceId}</td>
                                    <td className="px-6 py-4">{trx.description}</td>
                                    <td className="px-6 py-4">{trx.date}</td>
                                    <td className={`px-6 py-4 text-right font-bold ${trx.type === 'Ingreso' ? 'text-emerald-600' : 'text-rose-600'}`}>
