                        >
                            Guardar Nota
                        </button>
                    </div>
                </div>
            </div>
        )}

      </div>

      {/* Edit Client Modal */}
      {isEditModalOpen && editFormData && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-xl shadow-xl w-full max-w-2xl max-h-[90vh] overflow-y-auto animate-fade-in">
                <div className="bg-indigo-600 p-4 flex justify-between items-center text-white sticky top-0 z-10">
                    <h3 className="font-bold text-lg">Editar Cliente</h3>
