import React, { useState } from 'react';
import { Search, Plus, Download, TrendingUp, TrendingDown, Eye } from 'lucide-react';
import { useStore } from '../context/StoreContext';
import { LoanStatus } from '../types';
import { useNavigate } from 'react-router-dom';
import StatCard from '../components/StatCard';

const Loans: React.FC = () => {
  const { loans } = useStore();
  const navigate = useNavigate();
  const [filterTerm, setFilterTerm] = useState('');

  const filteredLoans = loans.filter(l => 
    l.clientName.toLowerCase().includes(filterTerm.toLowerCase()) || 
    l.id.toLowerCase().includes(filterTerm.toLowerCase())
  );

  // Global Calculations
  const totalLentGlobal = loans.reduce((acc, loan) => acc + loan.amount, 0);
  // Assuming "Collected" means TotalToPay - RemainingBalance (Principal + Interest paid so far)
  const totalCollectedGlobal = loans.reduce((acc, loan) => acc + (loan.totalToPay - loan.remainingBalance), 0);
  const totalOutstanding = loans.reduce((acc, loan) => acc + loan.remainingBalance, 0);

  return (
    <div className="space-y-6 animate-fade-in">

      {/* Header and Actions */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
           <h2 className="text-2xl font-bold text-slate-800">Gestión de Préstamos</h2>
           <p className="text-slate-500">Control detallado de cartera, capital y cobranza.</p>
        </div>
        <div className="flex gap-2">
           <button 
             onClick={() => navigate('/solicitud')}
             className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 flex items-center gap-2 shadow-sm transition-colors"
           >
             <Plus className="w-4 h-4" />
             <span className="text-sm font-medium">Nuevo Préstamo</span>
           </button>
           <button className="px-4 py-2 bg-white border border-slate-300 text-slate-700 rounded-lg hover:bg-slate-50 flex items-center gap-2 transition-colors">
             <Download className="w-4 h-4" />
             <span className="text-sm font-medium hidden md:inline">Exportar</span>
           </button>
        </div>
      </div>

      {/* Global Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <StatCard 
            title="Total Prestado Global" 
            value={`$${totalLentGlobal.toLocaleString()}`} 
            icon={TrendingUp} 
            color="text-indigo-600 bg-indigo-500" 
            trend="Capital Colocado"
            trendUp={true}
        />
        <StatCard 
            title="Total Cobrado Global" 
            value={`$${totalCollectedGlobal.toLocaleString()}`} 
            icon={TrendingDown} 
            color="text-emerald-600 bg-emerald-500" 
            trend="Recuperación + Interés"
            trendUp={true}
        />
        <StatCard 
            title="Cartera Restante" 
            value={`$${totalOutstanding.toLocaleString()}`} 
            icon={TrendingUp} 
            color="text-amber-600 bg-amber-500" 
            trend="Pendiente de Cobro"
            trendUp={false}
        />
      </div>

      {/* Loans Table */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
        <div className="p-4 border-b border-slate-100 bg-slate-50/50">
          <div className="relative max-w-md">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400 w-5 h-5" />
            <input 
              type="text" 
              value={filterTerm}
