import React, { useState } from 'react';
import { Search, Plus, Filter, AlertTriangle, HelpCircle, ChevronUp, ChevronDown, CheckCircle, Clock } from 'lucide-react';
import { useStore } from '../context/StoreContext';
import { LoanStatus } from '../types';
import { useNavigate } from 'react-router-dom';

const Loans: React.FC = () => {
  const { loans } = useStore();
  const navigate = useNavigate();
  const [filterTerm, setFilterTerm] = useState('');

  const filteredLoans = loans.filter(l => 
    l.clientName.toLowerCase().includes(filterTerm.toLowerCase()) || 
    l.id.toLowerCase().includes(filterTerm.toLowerCase())
  );

  const totalLentGlobal = loans.reduce((acc, loan) => acc + loan.amount, 0);
  const totalCollectedGlobal = loans.reduce((acc, loan) => acc + (loan.totalToPay - loan.remainingBalance), 0);

  // Helper to determine status style
  const getStatusStyle = (status: string, nextDate: string) => {
      if (status === LoanStatus.OVERDUE) return { badge: 'Vencido', color: 'bg-rose-600' };
      if (status === LoanStatus.PAID) return { badge: 'Pagado', color: 'bg-emerald-500' };

      const daysDiff = Math.ceil((new Date(nextDate).getTime() - new Date().getTime()) / (1000 * 3600 * 24));
      if (daysDiff < 0) return { badge: 'Atrasado', color: 'bg-rose-500' };
      return { badge: 'A tiempo', color: 'bg-emerald-400' };
  };

  return (
    <div className="max-w-3xl mx-auto space-y-0 h-screen flex flex-col bg-slate-50 -m-4 md:-m-8">

      {/* Header Bar */}
      <div className="bg-indigo-600 text-white p-4 flex justify-between items-center shadow-md z-10">
          <div className="flex items-center gap-4">
              <button onClick={() => navigate(-1)} className="text-white font-bold text-lg">X</button>
              <h2 className="text-lg font-bold">Préstamos ({filteredLoans.length}/{loans.length})</h2>
          </div>
          <div className="flex gap-4">
              <Plus className="w-6 h-6" onClick={() => navigate('/solicitud')} />
              <div className="flex flex-col gap-1">
                  <div className="w-1 h-1 bg-white rounded-full"></div>
                  <div className="w-1 h-1 bg-white rounded-full"></div>
                  <div className="w-1 h-1 bg-white rounded-full"></div>
              </div>
          </div>
      </div>

      {/* Summary Banner */}
      <div className="bg-emerald-100 flex justify-between px-4 py-1 text-xs font-bold border-b border-emerald-200">
          <span className="text-emerald-800">Total: RD$ {totalLentGlobal.toLocaleString(undefined, {minimumFractionDigits: 3})}</span>
          <span className="text-slate-600">Cobrado: RD$ {totalCollectedGlobal.toLocaleString(undefined, {minimumFractionDigits: 3})}</span>
      </div>

      {/* Search & Filter Bar */}
      <div className="bg-white p-3 border-b border-slate-200 sticky top-0 z-10">
          <div className="flex gap-2 mb-3">
             <div className="bg-indigo-500 rounded p-2 text-white"><Filter className="w-5 h-5" /></div>
             <div className="relative flex-1">
                 <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-300 w-5 h-5" />
                 <input 
                    type="text" 
                    value={filterTerm}
                    onChange={(e) => setFilterTerm(e.target.value)}
                    placeholder="Búscar cliente..." 
                    className="w-full pl-10 pr-4 py-2 border border-slate-200 rounded text-slate-700 focus:outline-none"
                 />
             </div>
             <div className="bg-blue-400 rounded-full p-2 text-white"><div className="w-5 h-5 rounded-full border-2 border-white"></div></div>
          </div>

          {/* Status Color Filters */}
          <div className="flex justify-between items-center px-2">
              <CheckCircle className="w-5 h-5 text-emerald-500" />
              <div className="w-6 h-6 bg-amber-200 transform -skew-x-12"></div>
              <div className="w-6 h-6 bg-orange-400 transform -skew-x-12"></div>
              <div className="w-6 h-6 bg-orange-600 transform -skew-x-12"></div>
              <div className="w-6 h-6 bg-rose-700 transform -skew-x-12"></div>
              <AlertTriangle className="w-6 h-6 text-slate-800 bg-white border border-slate-800 rounded p-0.5" />
              <HelpCircle className="w-6 h-6 text-indigo-500" />
          </div>
      </div>

      {/* Loans List */}
      <div className="flex-1 overflow-y-auto bg-slate-100 p-2 space-y-2 pb-20">
          {filteredLoans.map((loan) => {
              const statusInfo = getStatusStyle(loan.status, loan.nextPaymentDate);
              const daysAgo = Math.floor(Math.random() * 20) + 1; // Mock data

              return (
                <div key={loan.id} className="bg-white p-3 rounded shadow-sm border-l-4 border-indigo-500 relative">
                    {/* Status Badge */}
                    <span className={`absolute top-3 right-3 text-[10px] font-bold text-white px-2 py-0.5 rounded ${statusInfo.color}`}>
                        {statusInfo.badge}
                    </span>

                    {/* Header Row */}
                    <div className="text-[10px] text-slate-500 font-bold mb-1 flex items-center gap-1">
                        <span className="text-indigo-600">#{loan.id}</span>
                        <span>| {loan.frequency} | 1/{loan.durationWeeks} | {statusInfo.badge === 'A tiempo' ? 'Sin atraso' : `${daysAgo} Dias atrasado`}</span>
                    </div>

                    {/* Client Name */}
                    <h3 className="text-base font-bold text-slate-800 mb-1">{loan.clientName}</h3>

                    {/* Installment Info */}
                    <div className="text-xs text-slate-600 mb-1">
                        <span className="font-bold">RD${(loan.totalToPay / loan.durationWeeks).toFixed(2)}</span>
                        <span className="text-slate-500"> hace {daysAgo} dias | Prox. Cuota {loan.nextPaymentDate}</span>
                    </div>

                    {/* Capital Info & Amount Due */}
