                            <span className="mx-1">|</span>
                            <span>restante RD${loan.remainingBalance.toLocaleString(undefined, {minimumFractionDigits: 2})}</span>
                        </div>
                        <div className="font-bold text-slate-800 text-sm">
                            {statusInfo.badge === 'A tiempo' ? '$0.00' : `$${(loan.remainingBalance * 0.1).toLocaleString(undefined, {minimumFractionDigits: 2})}`}
                        </div>
                    </div>
                </div>
              );
          })}
      </div>

      {/* Floating Action / Scroll To Top */}
      <button className="fixed bottom-20 right-4 bg-indigo-500 text-white p-3 rounded-full shadow-lg">
          <ChevronUp className="w-6 h-6" />
