import { LoanStatus } from '../types';
import { useNavigate } from 'react-router-dom';

const Loans: React.FC = () => {
  const { loans } = useStore();
  const navigate = useNavigate();
  const [filterTerm, setFilterTerm] = useState('');

  const filteredLoans = loans.filter(l => 
    l.clientName.toLowerCase().includes(filterTerm.toLowerCase()) || 
    l.id.toLowerCase().includes(filterTerm.toLowerCase())
  );

  const totalLentGlobal = loans.reduce((acc, loan) => acc + loan.amount, 0);
  const totalCollectedGlobal = loans.reduce((acc, loan) => acc + (loan.totalToPay - loan.remainingBalance), 0);

  // Helper to determine status style
  const getStatusStyle = (status: string, nextDate: string) => {
      if (status === LoanStatus.OVERDUE) return { badge: 'Vencido', color: 'bg-rose-100 text-rose-700 border-rose-200' };
      if (status === LoanStatus.PAID) return { badge: 'Pagado', color: 'bg-emerald-100 text-emerald-700 border-emerald-200' };

      const daysDiff = Math.ceil((new Date(nextDate).getTime() - new Date().getTime()) / (1000 * 3600 * 24));
      if (daysDiff < 0) return { badge: 'Atrasado', color: 'bg-amber-100 text-amber-700 border-amber-200' };
      return { badge: 'A tiempo', color: 'bg-indigo-50 text-indigo-700 border-indigo-100' };
  };

  return (
    <div className="space-y-6 animate-fade-in">
      {/* Page Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
         <div>
             <h2 className="text-2xl font-bold text-slate-800">Control de Préstamos</h2>
             <p className="text-slate-500">Monitoreo en tiempo real de la cartera.</p>
         </div>
         <div className="flex gap-2">
             <button 
                 onClick={() => navigate('/solicitud')}
                 className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 flex items-center gap-2 shadow-sm transition-colors"
             >
                 <Plus className="w-4 h-4" />
                 <span className="text-sm font-medium">Nuevo Préstamo</span>
             </button>
         </div>
      </div>

      {/* Stats Summary */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100 flex justify-between items-center">
              <div>
                  <p className="text-xs text-slate-500 font-bold uppercase">Total Prestado</p>
                  <p className="text-xl font-bold text-slate-800">RD$ {totalLentGlobal.toLocaleString(undefined, {minimumFractionDigits: 2})}</p>
              </div>
              <div className="p-2 bg-slate-50 rounded-lg text-slate-400"><Clock className="w-5 h-5"/></div>
          </div>
          <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100 flex justify-between items-center">
              <div>
                  <p className="text-xs text-slate-500 font-bold uppercase">Total Cobrado</p>
                  <p className="text-xl font-bold text-emerald-600">RD$ {totalCollectedGlobal.toLocaleString(undefined, {minimumFractionDigits: 2})}</p>
              </div>
              <div className="p-2 bg-emerald-50 rounded-lg text-emerald-500"><CheckCircle className="w-5 h-5"/></div>
          </div>
      </div>

      {/* Filter Bar */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100 flex flex-col md:flex-row gap-4 items-center sticky top-0 z-10">
