                                              <div className="px-4 py-2 bg-slate-100/50 border-b border-slate-200 flex justify-between items-center">
                                                  <span className="text-xs font-bold text-slate-600 uppercase flex items-center gap-2">
                                                      Préstamo #{loanGroup.loan.id} 
                                                      <span className="text-slate-400">•</span>
