                            <Banknote className="w-4 h-4" /> Financiero
                        </h4>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div>
                                <label className="block text-sm font-medium text-slate-700 mb-1">Ingresos Mensuales</label>
                                <input 
                                    type="number" 
                                    className="w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none" 
                                    value={editFormData.income} 
                                    onChange={e => setEditFormData({...editFormData, income: Number(e.target.value)})} 
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-slate-700 mb-1">Estado del Cliente</label>
                                <select 
                                    className="w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none"
                                    value={editFormData.status} 
                                    onChange={e => setEditFormData({...editFormData, status: e.target.value as any})}
                                >
                                    <option value="Activo">Activo</option>
                                    <option value="Bloqueado">Bloqueado</option>
                                </select>
                            </div>
                        </div>
                    </div>

                    <div className="pt-4 flex gap-3 justify-end border-t border-slate-100">
