                             <p className="font-medium text-slate-800">RD${viewLoan.totalToPay.toLocaleString()}</p>
                         </div>
                     </div>

                     {/* Actions */}
                     <div className="space-y-3 pt-2">
                        <button 
                            onClick={() => goToPayment(viewLoan.id)}
                            className="w-full bg-emerald-500 text-white py-3 rounded-lg font-bold flex items-center justify-center gap-2 hover:bg-emerald-600 transition-colors shadow-md shadow-emerald-200">
                            <DollarSign className="w-5 h-5" />
                            Registrar Pago
                        </button>
                        <button className="w-full bg-white border border-slate-200 text-slate-700 py-3 rounded-lg font-bold flex items-center justify-center gap-2 hover:bg-slate-50 transition-colors">
                            <FileText className="w-5 h-5" />
                            Ver Tabla de Amortización
                        </button>
                        <button className="w-full text-indigo-600 text-sm font-medium hover:underline pt-2">
                            Ver Contrato Firmado
                        </button>
                     </div>
                 </div>
             </div>
          </div>
      )}

      {/* Receipt Modal - Paper Style */}
      {viewReceipt && (
           <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
              <div className="bg-slate-100 p-8 rounded-xl shadow-2xl relative max-w-sm w-full">
                  <button onClick={() => setViewReceipt(null)} className="absolute -top-4 -right-4 bg-white rounded-full p-2 shadow-lg hover:bg-slate-100">
                      <X className="w-5 h-5 text-slate-600" />
                  </button>

                  {/* Receipt Paper */}
                  <div className="bg-white p-6 shadow-[0_4px_6px_-1px_rgba(0,0,0,0.1),0_2px_4px_-1px_rgba(0,0,0,0.06)] relative receipt-tear-top">
                      <div className="text-center mb-6">
                          <div className="w-10 h-10 bg-indigo-600 rounded-lg mx-auto mb-2 flex items-center justify-center text-white font-bold">E</div>
                          <h3 className="font-bold text-slate-800 text-lg uppercase tracking-wider">Recibo de Pago</h3>
                          <p className="text-xs text-slate-500">{viewReceipt.date}</p>
                      </div>

                      <div className="border-t-2 border-dashed border-slate-200 py-4 space-y-3 text-sm">
                           <div className="flex justify-between">
                               <span className="text-slate-500">Recibí de:</span>
                               <span className="font-bold text-slate-800 uppercase">{client.name}</span>
                           </div>
                           <div className="flex justify-between">
                               <span className="text-slate-500">La suma de:</span>
                               <span className="font-bold text-slate-800">RD${viewReceipt.amount.toLocaleString()}</span>
                           </div>
                           <div className="flex justify-between">
                               <span className="text-slate-500">Concepto:</span>
                               <span className="font-medium text-slate-800">{viewReceipt.description}</span>
                           </div>
                           <div className="flex justify-between">
                               <span className="text-slate-500">Ref:</span>
                               <span className="font-mono text-slate-600">{viewReceipt.referenceId}</span>
                           </div>
                      </div>

                      <div className="mt-6 pt-6 border-t-2 border-slate-800">
                          <div className="flex justify-between items-end">
                              <div className="text-center">
                                  <div className="h-10 w-24 mb-1">
                                    <svg viewBox="0 0 100 30" className="w-full h-full stroke-slate-600 stroke-2 fill-none">
                                        <path d="M10,15 Q30,5 50,15 T90,15" />
                                    </svg>
                                  </div>
                                  <p className="text-[10px] text-slate-400 border-t border-slate-300 pt-1">Firma Autorizada</p>
                              </div>
                              <div className="text-right">
                                  <p className="text-2xl font-bold text-slate-800">RD${viewReceipt.amount.toLocaleString()}</p>
                              </div>
                          </div>
                      </div>
                  </div>

                  <div className="flex gap-2 mt-6">
                      <button className="flex-1 bg-indigo-600 text-white py-2 rounded-lg text-sm font-bold flex items-center justify-center gap-2 hover:bg-indigo-700 transition-colors">
                          <Printer className="w-4 h-4" /> Imprimir
                      </button>
                      <button className="flex-1 bg-white text-slate-700 border border-slate-200 py-2 rounded-lg text-sm font-bold flex items-center justify-center gap-2 hover:bg-slate-50 transition-colors">
                          <Share2 className="w-4 h-4" /> Enviar
                      </button>
                  </div>
              </div>
           </div>
      )}
    </div>
  );
};

const ActionButton: React.FC<{icon: any, label: string, onClick?: () => void, active?: boolean}> = ({icon: Icon, label, onClick, active}) => (
    <button onClick={onClick} className={`flex items-center justify-center gap-2 py-2 px-4 rounded-lg border transition-all ${active ? 'bg-indigo-600 text-white border-indigo-600 shadow-md' : 'bg-white text-slate-600 border-slate-200 hover:border-indigo-300 hover:text-indigo-600'}`}>
        <Icon className="w-4 h-4" />
        <span className="text-xs font-bold">{label}</span>
    </button>
);

const TabButton: React.FC<{label: string, active: boolean, onClick: () => void}> = ({label, active, onClick}) => (
    <button onClick={onClick} className={`px-6 py-3 text-sm font-medium border-b-2 transition-colors ${active ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-500 hover:text-slate-800'}`}>
        {label}
    </button>
);

const DetailRow: React.FC<{label: string, value: string}> = ({label, value}) => (
    <div className="border-b border-slate-50 pb-2">
        <span className="block text-xs font-bold text-slate-400 uppercase mb-1">{label}</span>
        <span className="block text-sm text-slate-800 font-medium">{value}</span>
    </div>
);

export default ClientDetail;

import React, { useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { 
  User, Phone, MapPin, ArrowLeft, Banknote, CalendarClock, 
  StickyNote, Landmark, Plus, Trash2, Edit, X, FileText, Printer, CheckCircle, 
  Receipt, ShoppingBag, MessageCircle, MoreHorizontal, Share2, Download, CreditCard, DollarSign, Calendar, Clock,
  File, Image as ImageIcon, Upload, ShieldCheck, FileCheck, Eye, AlertCircle
} from 'lucide-react';
import { useStore } from '../context/StoreContext';
import { LoanStatus, BankAccount, Client, Loan, Transaction, ClientDocument } from '../types';

const ClientDetail: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { 
    clients, loans, transactions, bankAccounts, clientNotes, clientDocuments,
    addBankAccount, removeBankAccount, addClientNote, updateClient,
    addClientDocument, removeClientDocument
  } = useStore();

  const client = clients.find(c => c.id === id);
  const [activeTab, setActiveTab] = useState<'general' | 'loans' | 'payments' | 'documents' | 'notes' | 'banks'>('general');

  // State for Documents
  const [isUploadModalOpen, setIsUploadModalOpen] = useState(false);
  const [uploadDocType, setUploadDocType] = useState<ClientDocument['type']>('Cedula');
  const [uploadDocTitle, setUploadDocTitle] = useState('');
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [previewDoc, setPreviewDoc] = useState<ClientDocument | null>(null);

  const [newBank, setNewBank] = useState<Partial<BankAccount>>({ bankName: '', accountNumber: '', accountType: 'Ahorro', holderName: '' });
  const [showBankForm, setShowBankForm] = useState(false);
  const [newNote, setNewNote] = useState('');

  // Edit State
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [editFormData, setEditFormData] = useState<Client | null>(null);

  const [viewLoan, setViewLoan] = useState<Loan | null>(null);
  const [viewReceipt, setViewReceipt] = useState<Transaction | null>(null);

  if (!client) {
    return <div className="p-8 text-center text-slate-500">Cliente no encontrado.</div>;
  }

  const clientLoans = loans.filter(l => l.clientId === client.id);
  const clientTransactions = transactions.filter(t => 
    t.referenceId && clientLoans.some(l => l.id === t.referenceId)
  );
  const clientBanks = bankAccounts.filter(b => b.clientId === client.id);
  const myNotes = clientNotes.filter(n => n.clientId === client.id);
  const myDocuments = clientDocuments.filter(d => d.clientId === client.id);

  const handleAddBank = (e: React.FormEvent) => {
    e.preventDefault();
    if(newBank.bankName && newBank.accountNumber) {
        addBankAccount({ ...newBank as BankAccount, id: Date.now().toString(), clientId: client.id });
        setNewBank({ bankName: '', accountNumber: '', accountType: 'Ahorro', holderName: '' });
        setShowBankForm(false);
    }
  };

  const handleAddNote = () => {
    if(!newNote.trim()) return;
    addClientNote({ id: Date.now().toString(), clientId: client.id, content: newNote, date: new Date().toISOString().split('T')[0], createdBy: 'Admin' });
    setNewNote('');
  };

  const handleEditClick = () => {
      setEditFormData({ ...client });
      setIsEditModalOpen(true);
  };

  const handleUpdateClient = (e: React.FormEvent) => {
      e.preventDefault();
      if(editFormData) {
          updateClient(editFormData);
          setIsEditModalOpen(false);
      }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0]) {
          setSelectedFile(e.target.files[0]);
          if (!uploadDocTitle) {
              setUploadDocTitle(e.target.files[0].name);
          }
      }
  };

  const handleUploadSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      if (!selectedFile) return;

      const fileUrl = URL.createObjectURL(selectedFile);

      const newDoc: ClientDocument = {
          id: `DOC-${Date.now()}`,
          clientId: client.id,
          title: uploadDocTitle || 'Documento sin título',
          type: uploadDocType,
          fileUrl: fileUrl,
          fileType: selectedFile.type,
          uploadDate: new Date().toISOString().split('T')[0]
      };

      addClientDocument(newDoc);

      // Reset
      setIsUploadModalOpen(false);
      setSelectedFile(null);
      setUploadDocTitle('');
      setUploadDocType('Cedula');
  };

  const goToPayment = (loanId: string) => {
      navigate('/pagos', { state: { loanId } });
  };

  const getDocIcon = (type: string, fileType: string) => {
      if (fileType.startsWith('image/')) return <ImageIcon className="w-8 h-8 text-indigo-500" />;
      if (fileType.includes('pdf')) return <FileText className="w-8 h-8 text-rose-500" />;
      return <File className="w-8 h-8 text-slate-500" />;
  };

  const getDocBadgeColor = (type: string) => {
      switch(type) {
          case 'Cedula': return 'bg-blue-100 text-blue-700';
          case 'Contrato': return 'bg-emerald-100 text-emerald-700';
          case 'Garantia': return 'bg-amber-100 text-amber-700';
          default: return 'bg-slate-100 text-slate-700';
      }
  };

  return (
    <div className="max-w-5xl mx-auto min-h-screen relative pb-10 space-y-6 animate-fade-in">

      {/* Header */}
      <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
               <button onClick={() => navigate('/clientes')} className="p-2 hover:bg-slate-200 rounded-full transition-colors">
                  <ArrowLeft className="w-6 h-6 text-slate-600" />
               </button>
               <div>
                  <h1 className="text-2xl font-bold text-slate-800">{client.name}</h1>
                  <p className="text-slate-500 text-sm flex items-center gap-2">ID: {client.id} <span className="w-1 h-1 bg-slate-300 rounded-full"></span> {client.status}</p>
               </div>
          </div>
          <button className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-white rounded-lg transition-colors border border-transparent hover:border-slate-200">
              <MoreHorizontal className="w-6 h-6" />
          </button>
      </div>

      {/* Profile Card */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-100 p-6">
          <div className="flex flex-col md:flex-row gap-6 items-center md:items-start">
               <div className="w-24 h-24 rounded-full bg-slate-100 overflow-hidden border-4 border-white shadow-md flex items-center justify-center">
                    <span className="text-3xl font-bold text-slate-400">{client.name.charAt(0)}</span>
               </div>

               <div className="flex-1 flex flex-col items-center md:items-start text-center md:text-left">
                   <div className="grid grid-cols-2 md:grid-cols-4 gap-4 w-full mb-6">
                       <ActionButton icon={Banknote} label="Préstamos" onClick={() => setActiveTab('loans')} active={activeTab==='loans'} />
                       <ActionButton icon={Receipt} label="Recibos" onClick={() => setActiveTab('payments')} active={activeTab==='payments'} />
                       <ActionButton icon={FileCheck} label="Documentos" onClick={() => setActiveTab('documents')} active={activeTab==='documents'} />
                       <ActionButton icon={Edit} label="Editar" onClick={handleEditClick} />
                   </div>
               </div>
          </div>

          <div className="flex border-b border-slate-100 mt-4 overflow-x-auto">
              <TabButton label="Datos Generales" active={activeTab === 'general'} onClick={() => setActiveTab('general')} />
              <TabButton label="Documentos Digitales" active={activeTab === 'documents'} onClick={() => setActiveTab('documents')} />
              <TabButton label="Bancos" active={activeTab === 'banks'} onClick={() => setActiveTab('banks')} />
              <TabButton label="Notas" active={activeTab === 'notes'} onClick={() => setActiveTab('notes')} />
          </div>
      </div>

      {/* Content Area */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-100 min-h-[400px]">
        {activeTab === 'general' && (
            <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-y-6 gap-x-12">
                 <DetailRow label="ID del cliente" value={client.id} />
                 <DetailRow label="Cédula" value={client.cedula} />
                 <DetailRow label="Nombre completo" value={client.name} />
                 <DetailRow label="Sexo" value={client.sex} />
                 <DetailRow label="Ocupación" value={client.occupation} />
                 <DetailRow label="Celular" value={client.phone} />
                 <DetailRow label="Tel. Casa" value={client.phoneHome || '-'} />
                 <DetailRow label="Ingresos" value={`$${client.income.toLocaleString()}`} />
                 <DetailRow label="Dirección" value={client.address} />
            </div>
        )}

        {activeTab === 'loans' && (
             <div className="p-6 space-y-4">
                 <h3 className="font-bold text-slate-800 mb-4">Préstamos Activos e Históricos</h3>
                 {clientLoans.length === 0 ? <p className="text-slate-400 text-center py-8">No hay préstamos.</p> : clientLoans.map(loan => (
                     <div 
                         key={loan.id} 
                         onClick={() => setViewLoan(loan)}
                         className="p-4 rounded-lg border border-slate-100 flex justify-between items-center hover:bg-slate-50 transition-colors cursor-pointer"
                     >
                         <div>
                             <p className="font-bold text-indigo-600 flex items-center gap-2">
                                 <Banknote className="w-4 h-4" /> Préstamo #{loan.id}
                             </p>
                             <p className="text-sm text-slate-500 mt-1">Monto: ${loan.amount.toLocaleString()} • Bal: ${loan.remainingBalance.toLocaleString()}</p>
                         </div>
                         <div className="flex items-center gap-3">
                             <span className={`text-xs font-bold px-2 py-1 rounded ${loan.status === 'Activo' ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-100 text-slate-600'}`}>{loan.status}</span>
                             <button className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-white rounded-full transition-colors"><FileText className="w-5 h-5" /></button>
                         </div>
                     </div>
                 ))}
             </div>
        )}

        {activeTab === 'payments' && (
            <div className="p-6 space-y-2">
                 <h3 className="font-bold text-slate-800 mb-4">Historial de Pagos</h3>
                 {clientTransactions.length === 0 ? <p className="text-slate-400 text-center py-8">No hay transacciones.</p> : clientTransactions.map(trx => (
                     <div key={trx.id} className="p-3 rounded-lg border border-slate-100 flex justify-between items-center hover:bg-slate-50">
                         <div className="flex items-center gap-3">
                             <div className="p-2 bg-emerald-50 text-emerald-600 rounded-lg">
                                 <CheckCircle className="w-4 h-4" />
                             </div>
                             <div>
                                 <p className="font-bold text-slate-700 text-sm">{trx.description}</p>
                                 <p className="text-xs text-slate-400">{trx.date}</p>
                             </div>
                         </div>
                         <div className="flex items-center gap-4">
                             <span className="font-bold text-emerald-600">+${trx.amount.toLocaleString()}</span>
                             <button onClick={() => setViewReceipt(trx)} className="text-indigo-500 hover:text-indigo-700 text-xs font-bold underline">Ver Recibo</button>
                         </div>
                     </div>
                 ))}
            </div>
        )}

        {activeTab === 'documents' && (
