import { Role, Permission, User } from '../types';

const Settings: React.FC = () => {
  const { companySettings, updateCompanySettings, roles, addRole, deleteRole, users, registerUser } = useStore();
  const [activeTab, setActiveTab] = useState<'company' | 'roles' | 'users'>('company');

  // Company Form State
  const [companyForm, setCompanyForm] = useState(companySettings);

  // Role Form State
  const [isRoleModalOpen, setIsRoleModalOpen] = useState(false);
  const [newRole, setNewRole] = useState<{name: string, description: string, permissions: Permission[]}>({
    name: '', description: '', permissions: []
  });

  // User Form State
  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [newUser, setNewUser] = useState<Partial<User>>({
    name: '', email: '', password: '', roleId: 'collector', status: 'Active'
  });

  const availablePermissions: {id: Permission, label: string}[] = [
    { id: 'manage_loans', label: 'Gestionar Préstamos' },
    { id: 'manage_clients', label: 'Gestionar Clientes' },
    { id: 'manage_users', label: 'Gestionar Usuarios' },
    { id: 'manage_settings', label: 'Configuración Global' },
    { id: 'view_reports', label: 'Ver Reportes Financieros' },
    { id: 'approve_loans', label: 'Aprobar Solicitudes' },
  ];

  const handleSaveCompany = (e: React.FormEvent) => {
    e.preventDefault();
    updateCompanySettings(companyForm);
    alert("Datos de la empresa actualizados correctamente.");
  };

  const handleSaveRole = (e: React.FormEvent) => {
    e.preventDefault();
    if(newRole.name) {
      addRole({
        id: newRole.name.toLowerCase().replace(/\s+/g, '_'),
        name: newRole.name,
        description: newRole.description,
        permissions: newRole.permissions
      });
      setIsRoleModalOpen(false);
      setNewRole({ name: '', description: '', permissions: [] });
    }
  };

  const togglePermission = (perm: Permission) => {
    setNewRole(prev => {
      const hasPerm = prev.permissions.includes(perm);
      return {
        ...prev,
        permissions: hasPerm 
          ? prev.permissions.filter(p => p !== perm)
          : [...prev.permissions, perm]
      };
    });
  };

  const handleSaveUser = (e: React.FormEvent) => {
    e.preventDefault();
    if(newUser.name && newUser.email && newUser.password) {
      registerUser({
        id: Date.now().toString(),
        name: newUser.name,
        email: newUser.email,
        password: newUser.password,
        roleId: newUser.roleId || 'collector',
        status: 'Active'
      });
      setIsUserModalOpen(false);
      setNewUser({ name: '', email: '', password: '', roleId: 'collector' });
    }
  };

  return (
    <div className="max-w-6xl mx-auto space-y-6 animate-fade-in pb-10">
      <div>
        <h2 className="text-2xl font-bold text-slate-800">Configuración</h2>
