                  <button onClick={() => setIsRoleModalOpen(true)} className="bg-indigo-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-indigo-700 flex items-center gap-2">
                    <Plus className="w-4 h-4" /> Crear Rol
