                             <option value="Contrato">Contrato Firmado</option>
                             <option value="Garantia">Garantía / Aval</option>
                             <option value="Otro">Otro</option>
                         </select>
                     </div>
                     <div className="border-2 border-dashed border-slate-300 rounded-xl p-6 text-center hover:bg-slate-50 transition-colors cursor-pointer relative">
                         <input type="file" className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" onChange={handleFileChange} accept="image/*,.pdf" />
                         {selectedFile ? (
                             <div className="flex flex-col items-center">
                                 <FileCheck className="w-8 h-8 text-emerald-500 mb-2" />
                                 <span className="text-sm font-medium text-slate-700">{selectedFile.name}</span>
