                         )}
                     </div>
                     <button type="submit" className="w-full bg-indigo-600 text-white py-2 rounded-lg font-bold hover:bg-indigo-700 disabled:opacity-50" disabled={!selectedFile}>
                         Subir Documento
                     </button>
                 </form>
             </div>
        </div>
      )}

      {/* Document Preview Modal */}
      {previewDoc && (
          <div className="fixed inset-0 bg-black/90 z-50 flex items-center justify-center p-4 backdrop-blur-sm" onClick={() => setPreviewDoc(null)}>
              <div className="relative max-w-4xl w-full max-h-[90vh] flex flex-col items-center">
                  <button className="absolute -top-10 right-0 text-white hover:text-slate-300" onClick={() => setPreviewDoc(null)}>
                      <X className="w-8 h-8" />
                  </button>
                  {previewDoc.fileType.startsWith('image/') ? (
                      <img src={previewDoc.fileUrl} alt={previewDoc.title} className="max-w-full max-h-[85vh] object-contain rounded-lg" />
                  ) : (
                      <div className="bg-white p-10 rounded-lg text-center">
                          <FileText className="w-16 h-16 text-slate-400 mx-auto mb-4" />
                          <p className="text-lg font-bold">{previewDoc.title}</p>
                          <p className="text-slate-500 mb-4">Vista previa no disponible para este formato.</p>
                          <a href={previewDoc.fileUrl} download className="text-indigo-600 hover:underline">Descargar Archivo</a>
                      </div>
                  )}
                  <p className="text-white mt-4 font-medium">{previewDoc.title}</p>
              </div>
          </div>
      )}
    </div>
  );
};

