export default Loans;

import React, { useState } from 'react';
import { Search, Plus, Filter, Clock, X, Banknote, Calendar, CreditCard, DollarSign, FileText, Printer, RefreshCw, Calculator, ChevronRight, CheckCircle } from 'lucide-react';
import { useStore } from '../context/StoreContext';
import { LoanStatus, Loan } from '../types';
import { useNavigate } from 'react-router-dom';

const Loans: React.FC = () => {
  const { loans, companySettings, refinanceLoan } = useStore();
  const navigate = useNavigate();
  const [filterTerm, setFilterTerm] = useState('');
  const [selectedLoan, setSelectedLoan] = useState<Loan | null>(null);
  const [activeTab, setActiveTab] = useState<'summary' | 'amortization' | 'refinance'>('summary');

  // Refinance State
  const [refinanceAmount, setRefinanceAmount] = useState<number>(0);
  const [refinanceWeeks, setRefinanceWeeks] = useState<number>(12);
  const [refinanceInterest, setRefinanceInterest] = useState<number>(10);

  const filteredLoans = loans.filter(l => 
    l.clientName.toLowerCase().includes(filterTerm.toLowerCase()) || 
    l.id.toLowerCase().includes(filterTerm.toLowerCase())
  );

  const totalLentGlobal = loans.reduce((acc, loan) => acc + loan.amount, 0);
  const totalCollectedGlobal = loans.reduce((acc, loan) => acc + (loan.totalToPay - loan.remainingBalance), 0);

  const getStatusStyle = (status: string, nextDate: string) => {
      if (status === LoanStatus.OVERDUE) return { badge: 'Vencido', color: 'bg-rose-100 text-rose-700 border-rose-200' };
      if (status === LoanStatus.PAID) return { badge: 'Pagado', color: 'bg-emerald-100 text-emerald-700 border-emerald-200' };

      const daysDiff = Math.ceil((new Date(nextDate).getTime() - new Date().getTime()) / (1000 * 3600 * 24));
      if (daysDiff < 0) return { badge: 'Atrasado', color: 'bg-amber-100 text-amber-700 border-amber-200' };
      return { badge: 'A tiempo', color: 'bg-indigo-50 text-indigo-700 border-indigo-100' };
  };

  const goToPayment = (loanId: string) => {
      navigate('/pagos', { state: { loanId } });
  };

  const handleRefinance = () => {
    if(!selectedLoan) return;
    refinanceLoan(selectedLoan.id, {
        clientId: selectedLoan.clientId,
        clientName: selectedLoan.clientName,
        amount: refinanceAmount,
        interestRate: refinanceInterest,
        durationWeeks: refinanceWeeks,
        frequency: selectedLoan.frequency,
        startDate: new Date().toISOString().split('T')[0],
        nextPaymentDate: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]
    });
    alert(`Préstamo refinanciado con éxito. Se ha cerrado el préstamo ${selectedLoan.id} y creado uno nuevo.`);
    setSelectedLoan(null);
  };

  // Printing Function using a popup window
  const handlePrintContract = (loan: Loan) => {
    const printWindow = window.open('', '', 'width=800,height=600');
    if (!printWindow) return;

    const htmlContent = `
      <html>
        <head>
          <title>Contrato Préstamo ${loan.id}</title>
          <style>
            body { font-family: 'Times New Roman', serif; padding: 40px; line-height: 1.6; }
            h1, h2 { text-align: center; }
            .header { text-align: center; margin-bottom: 40px; border-bottom: 2px solid #000; padding-bottom: 20px; }
            .content { margin-bottom: 50px; text-align: justify; }
            .details { margin: 20px 0; border: 1px solid #ddd; padding: 20px; }
            .details-row { display: flex; justify-content: space-between; margin-bottom: 10px; }
            .signatures { margin-top: 100px; display: flex; justify-content: space-between; }
            .sig-line { border-top: 1px solid #000; width: 40%; text-align: center; padding-top: 10px; }
          </style>
        </head>
        <body>
          <div class="header">
            <h1>${companySettings.name}</h1>
            <p>${companySettings.address} | ${companySettings.phone}</p>
            <p>RNC: ${companySettings.rnc}</p>
          </div>

          <h2>CONTRATO DE PRÉSTAMO</h2>

          <div class="content">
            <p>En la ciudad de Santo Domingo, a los ${new Date().toLocaleDateString()}...</p>
            <p>Entre <strong>${companySettings.name}</strong> y el Sr/Sra <strong>${loan.clientName}</strong>, se acuerda el siguiente préstamo:</p>
          </div>

          <div class="details">
             <div class="details-row"><strong>Código Préstamo:</strong> <span>${loan.id}</span></div>
             <div class="details-row"><strong>Monto Capital:</strong> <span>${companySettings.currency} ${loan.amount.toLocaleString()}</span></div>
             <div class="details-row"><strong>Interés:</strong> <span>${loan.interestRate}%</span></div>
             <div class="details-row"><strong>Total a Pagar:</strong> <span>${companySettings.currency} ${loan.totalToPay.toLocaleString()}</span></div>
             <div class="details-row"><strong>Frecuencia:</strong> <span>${loan.frequency}</span></div>
             <div class="details-row"><strong>Duración:</strong> <span>${loan.durationWeeks} cuotas</span></div>
          </div>

          <div class="content">
            <p>El deudor se compromete a pagar el monto total detallado anteriormente en las fechas estipuladas. ${companySettings.termsAndConditions}</p>
          </div>

          <div class="signatures">
            <div class="sig-line">Firma Representante</div>
            <div class="sig-line">Firma Cliente</div>
          </div>
        </body>
      </html>
    `;

    printWindow.document.write(htmlContent);
    printWindow.document.close();
    printWindow.focus();
    printWindow.print();
  };

  // Calculate Amortization for Visualization
  const getAmortizationTable = (loan: Loan) => {
      const rows = [];
      const paymentPerPeriod = loan.totalToPay / loan.durationWeeks;
      let currentDate = new Date(loan.startDate);
      let balance = loan.totalToPay;

      for (let i = 1; i <= loan.durationWeeks; i++) {
          currentDate.setDate(currentDate.getDate() + 7); // Assume weekly for simplicity in display
          balance -= paymentPerPeriod;
          rows.push({
              period: i,
              date: currentDate.toLocaleDateString(),
              amount: paymentPerPeriod,
              balance: Math.max(0, balance)
          });
      }
      return rows;
  };

  return (
    <div className="space-y-6 animate-fade-in relative">
      {/* Page Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
