      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
          title="Cartera por Cobrar" 
          value={`$${totalPortfolio.toLocaleString()}`} 
          trend="+12%" 
          trendUp={true} 
          icon={Banknote} 
          color="text-emerald-600 bg-emerald-500" 
        />
        <StatCard 
          title="Clientes Activos" 
          value={activeClients.toString()} 
          trend="+5%" 
          trendUp={true} 
          icon={Users} 
          color="text-blue-600 bg-blue-500" 
        />
        <StatCard 
          title="Mora / Atrasos" 
          value={`$${overdueAmount.toLocaleString()}`} 
          trend={overdueAmount > 0 ? "Atención" : "Excelente"} 
          trendUp={overdueAmount === 0} 
          icon={AlertTriangle} 
          color="text-amber-600 bg-amber-500" 
        />
        <StatCard 
          title="Balance en Caja" 
          value={`$${stats.balance.toLocaleString()}`} 
          trend="Disponible" 
          trendUp={true} 
          icon={Wallet} 
          color="text-purple-600 bg-purple-500" 
        />
      </div>

      {/* Main Chart */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <div className="flex justify-between items-center mb-6">
            <h3 className="font-bold text-slate-800">Flujo de Caja Anual</h3>
            <select className="bg-slate-50 border border-slate-200 rounded-md text-sm px-2 py-1 outline-none text-slate-600">
              <option>Este año</option>
            </select>
          </div>
          <div className="h-72 w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={data} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorIncome" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#8b5cf6" stopOpacity={0.8}/>
                    <stop offset="95%" stopColor="#8b5cf6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12}} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12}} prefix="$" />
                <CartesianGrid vertical={false} stroke="#e2e8f0" strokeDasharray="3 3" />
                <Tooltip 
                  contentStyle={{backgroundColor: '#fff', borderRadius: '8px', border: '1px solid #e2e8f0', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}}
                  itemStyle={{color: '#1e293b'}}
                />
                <Area type="monotone" dataKey="income" stroke="#8b5cf6" strokeWidth={2} fillOpacity={1} fill="url(#colorIncome)" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Recent Activity */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <h3 className="font-bold text-slate-800 mb-4">Actividad Reciente</h3>
          <div className="space-y-4">
            {recentTransactions.length === 0 ? (
                <p className="text-slate-400 text-sm">No hay movimientos recientes.</p>
            ) : (
                recentTransactions.map((t) => (
                <div key={t.id} className="flex items-center justify-between pb-3 border-b border-slate-50 last:border-0 last:pb-0">
                    <div className="flex items-center gap-3">
                    <div className={`p-2 rounded-full ${t.type === 'Ingreso' ? 'bg-emerald-100 text-emerald-600' : 'bg-rose-100 text-rose-600'}`}>
                        {t.type === 'Ingreso' ? <ArrowDownRight className="w-4 h-4" /> : <ArrowUpRight className="w-4 h-4" />}
                    </div>
                    <div className="overflow-hidden">
                        <p className="text-sm font-medium text-slate-800 truncate w-32">{t.description}</p>
                        <p className="text-xs text-slate-500">{t.date}</p>
                    </div>
                    </div>
                    <span className={`text-sm font-bold ${t.type === 'Ingreso' ? 'text-emerald-600' : 'text-slate-800'}`}>
                    {t.type === 'Ingreso' ? '+' : '-'}${t.amount.toLocaleString()}
