                                              <div className="px-4 py-2 bg-slate-100/50 border-b border-slate-200 flex justify-between items-center">
                                                  <span className="text-xs font-bold text-slate-600 uppercase flex items-center gap-2">
                                                      Préstamo #{loanGroup.loan.id} 
                                                      <span className="text-slate-400">•</span>
                                                      {loanGroup.loan.frequency}
                                                  </span>
                                                  <button 
                                                      onClick={() => {
                                                          setActiveTab('registrar');
                                                          setSelectedLoanId(loanGroup.loan.id);
                                                      }}
                                                      className="text-xs font-bold text-indigo-600 hover:text-indigo-800 hover:underline"
                                                  >
                                                      Ir a Pagar
                                                  </button>
                                              </div>
                                              <div className="divide-y divide-slate-100">
                                                  {loanGroup.installments.map(inst => (
                                                      <div key={`${loanGroup.loan.id}-${inst.number}`} className="flex justify-between items-center p-3 hover:bg-indigo-50/30 transition-colors">
                                                          <div className="flex items-center gap-4">
                                                              <div className="w-8 h-8 rounded-lg bg-slate-100 text-slate-500 flex items-center justify-center text-xs font-bold font-mono">
