                                                          </div>

                                                          <div className="text-right flex items-center gap-4">
                                                              <div>
                                                                  <p className="font-bold text-slate-700">RD${(inst.amount - inst.paidAmount).toLocaleString()}</p>
                                                                  <span className={`text-[10px] font-bold uppercase px-1.5 py-0.5 rounded ${
                                                                      inst.status === 'Atrasado' ? 'bg-rose-100 text-rose-600' : 
                                                                      inst.status === 'Parcial' ? 'bg-amber-100 text-amber-600' : 'bg-slate-100 text-slate-500'
                                                                  }`}>
                                                                      {inst.status}
                                                                  </span>
                                                              </div>
                                                              <button 
                                                                  onClick={() => {
                                                                      setActiveTab('registrar');
                                                                      setSelectedLoanId(loanGroup.loan.id);
                                                                      setPaymentMode('cuotas');
                                                                      setPayAmount((inst.amount - inst.paidAmount).toFixed(2));
                                                                      setPayNote(`Pago cuota #${inst.number}`);
                                                                  }}
                                                                  className="p-2 border border-indigo-200 text-indigo-600 rounded hover:bg-indigo-600 hover:text-white transition-colors"
                                                                  title="Cobrar esta cuota"
                                                              >
                                                                  <CreditCard className="w-4 h-4" />
                                                              </button>
                                                          </div>
                                                      </div>
                                                  ))}
                                              </div>
                                          </div>
                                      ))}
                                  </div>
                              )}
                          </div>
                      );
                  })
              )}
          </div>
      )}

      {/* Success Modal */}
      {successPaymentData && (
          <PaymentSuccessModal 
             data={successPaymentData} 
             onClose={() => setSuccessPaymentData(null)} 
          />
      )}
    </div>
  );
};

