    const whatsappLink = `https://wa.me/?text=${encodedMessage}`;
    const mailLink = `mailto:?subject=Comprobante de Pago - ${data.clientName}&body=${encodedMessage}`;

    return (
        <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
            <div className="bg-white rounded-2xl shadow-2xl w-full max-w-sm p-6 animate-fade-in text-center relative">
