                    <p className="text-3xl font-bold text-slate-800">RD${data.amount.toLocaleString()}</p>
                    <div className="w-full h-px bg-slate-200 my-3"></div>
                    <div className="flex justify-between text-sm">
                        <span className="text-slate-500">Nuevo Balance</span>
                        <span className="font-bold text-indigo-600">RD${data.balance.toLocaleString()}</span>
