                      </div>
                      <button className="flex items-center gap-2 bg-slate-800 text-white px-4 py-2.5 rounded-lg text-sm font-bold hover:bg-slate-700 transition-colors shadow-sm"><Download className="w-4 h-4" /> Exportar</button>
