                  {/* 2FA Card (Mock) */}
                  <div className="bg-white rounded-xl shadow-sm border border-slate-100 p-6 opacity-90">
                       <h3 className="font-bold text-lg text-slate-800 mb-4 pb-2 border-b border-slate-100 flex items-center gap-2">
