                             <span className="font-medium text-slate-800">{user.name}</span>
                           </div>
                         </td>
                         <td className="px-6 py-4">
                           <span className="px-2 py-1 bg-slate-100 text-slate-600 rounded text-xs border border-slate-200 uppercase font-bold">
                             {roles.find(r => r.id === user.roleId)?.name}
                           </span>
                         </td>
                         <td className="px-6 py-4">
                           <span className="px-2 py-1 bg-emerald-100 text-emerald-600 rounded-full text-xs font-bold flex items-center gap-1 w-fit">
                             <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full"></span> Active
                           </span>
                         </td>
                         <td className="px-6 py-4 text-sm text-slate-500">{user.email}</td>
                       </tr>
                     ))}
                   </tbody>
                 </table>
               </div>
            </div>
          )}

           {/* Audit Logs */}
           {activeTab === 'audit' && (
            <div className="space-y-6 animate-fade-in">
               <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100">
                  <h3 className="font-bold text-slate-800 flex items-center gap-2">
                      <Activity className="w-5 h-5 text-indigo-500" /> Registro de Auditoría
                  </h3>
                  <p className="text-sm text-slate-500">Historial completo de acciones y cambios en el sistema.</p>
               </div>

               <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
                 <div className="overflow-x-auto">
                    <table className="w-full text-left">
                    <thead className="bg-slate-50 border-b border-slate-200 text-slate-500 text-xs uppercase">
                        <tr>
                        <th className="px-6 py-4 font-semibold">Fecha / Hora</th>
                        <th className="px-6 py-4 font-semibold">Usuario</th>
                        <th className="px-6 py-4 font-semibold">Acción</th>
                        <th className="px-6 py-4 font-semibold">Detalles</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {auditLogs.map(log => (
                        <tr key={log.id} className="hover:bg-slate-50">
                            <td className="px-6 py-4 text-xs font-mono text-slate-500 whitespace-nowrap">
                                {new Date(log.timestamp).toLocaleString()}
                            </td>
                            <td className="px-6 py-4">
                                <span className="font-bold text-slate-700 text-sm">{log.userName}</span>
                            </td>
                            <td className="px-6 py-4">
                                <span className="px-2 py-1 bg-indigo-50 text-indigo-700 rounded border border-indigo-100 text-xs font-medium">
                                    {log.action}
                                </span>
                            </td>
                            <td className="px-6 py-4 text-sm text-slate-600 max-w-md truncate" title={log.details}>
                                {log.details}
                            </td>
                        </tr>
                        ))}
                    </tbody>
                    </table>
                 </div>
               </div>
            </div>
          )}

        </div>
      </div>

      {/* Create Role Modal */}
      {isRoleModalOpen && (
        <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg p-6 animate-fade-in">
             <div className="flex justify-between items-center mb-6">
               <h3 className="font-bold text-lg text-slate-800">Crear Nuevo Rol</h3>
               <button onClick={() => setIsRoleModalOpen(false)}><X className="w-5 h-5 text-slate-400" /></button>
             </div>

             <form onSubmit={handleSaveRole} className="space-y-4">
               <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Nombre del Rol</label>
                  <input type="text" required className="w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500"
                    placeholder="Ej. Supervisor de Caja"
                    value={newRole.name} onChange={e => setNewRole({...newRole, name: e.target.value})} />
               </div>
               <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Descripción</label>
                  <input type="text" className="w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500"
                    placeholder="Breve descripción de responsabilidades"
                    value={newRole.description} onChange={e => setNewRole({...newRole, description: e.target.value})} />
               </div>

               <div>
                 <label className="block text-sm font-medium text-slate-700 mb-2">Permisos Asignados</label>
                 <div className="grid grid-cols-2 gap-2">
                   {availablePermissions.map(perm => (
                     <div 
                        key={perm.id} 
                        onClick={() => togglePermission(perm.id)}
                        className={`p-2 border rounded-lg cursor-pointer text-sm flex items-center gap-2 transition-colors ${newRole.permissions.includes(perm.id) ? 'bg-indigo-50 border-indigo-200 text-indigo-700' : 'hover:bg-slate-50 text-slate-600'}`}
                     >
                        <div className={`w-4 h-4 rounded border flex items-center justify-center ${newRole.permissions.includes(perm.id) ? 'bg-indigo-600 border-indigo-600 text-white' : 'border-slate-300'}`}>
                           {newRole.permissions.includes(perm.id) && <Check className="w-3 h-3" />}
                        </div>
                        {perm.label}
                     </div>
                   ))}
                 </div>
               </div>

               <button type="submit" className="w-full bg-indigo-600 text-white py-2 rounded-lg font-bold hover:bg-indigo-700 mt-4">
                 Guardar Rol
               </button>
             </form>
          </div>
        </div>
      )}

      {/* Create User Modal */}
      {isUserModalOpen && (
        <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
           <div className="bg-white rounded-xl shadow-2xl w-full max-w-md p-6 animate-fade-in">
             <div className="flex justify-between items-center mb-6">
               <h3 className="font-bold text-lg text-slate-800">Registrar Usuario</h3>
               <button onClick={() => setIsUserModalOpen(false)}><X className="w-5 h-5 text-slate-400" /></button>
             </div>

             <form onSubmit={handleSaveUser} className="space-y-4">
                <div>
                   <label className="block text-sm font-medium text-slate-700 mb-1">Nombre</label>
                   <input type="text" required className="w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500"
                     value={newUser.name} onChange={e => setNewUser({...newUser, name: e.target.value})} />
                </div>
                <div>
                   <label className="block text-sm font-medium text-slate-700 mb-1">Email</label>
                   <input type="email" required className="w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500"
                     value={newUser.email} onChange={e => setNewUser({...newUser, email: e.target.value})} />
                </div>
                <div>
                   <label className="block text-sm font-medium text-slate-700 mb-1">Contraseña Temporal</label>
                   <input type="text" required className="w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500"
                     value={newUser.password} onChange={e => setNewUser({...newUser, password: e.target.value})} />
                </div>
                <div>
                   <label className="block text-sm font-medium text-slate-700 mb-1">Rol Asignado</label>
                   <select className="w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500 bg-white"
                     value={newUser.roleId} onChange={e => setNewUser({...newUser, roleId: e.target.value})}>
                     {roles.map(r => (
                       <option key={r.id} value={r.id}>{r.name}</option>
                     ))}
                   </select>
                </div>

                <button type="submit" className="w-full bg-emerald-600 text-white py-2 rounded-lg font-bold hover:bg-emerald-700 mt-4">
                  Crear Usuario
                </button>
             </form>
           </div>
        </div>
      )}

    </div>
  );
};

export default Settings;

export enum LoanStatus {
  PENDING = 'Pendiente',
  ACTIVE = 'Activo',
  PAID = 'Pagado',
  OVERDUE = 'Atrasado',
  REJECTED = 'Rechazado'
}

export interface Client {
  id: string;
  name: string;
  sex: 'Masculino' | 'Femenino' | 'Otro';
  occupation: string;
  phone: string; // Celular / WhatsApp
  phoneHome?: string; // Teléfono Casa
  cedula: string;
  address: string;
  income: number; // Ingresos mensuales
  creditScore: number; // 0 - 100
  status: 'Activo' | 'Bloqueado';
  email?: string;
  joinedDate: string;
}

export interface BankAccount {
  id: string;
  clientId: string;
  bankName: string;
  accountNumber: string;
  accountType: 'Ahorro' | 'Corriente';
  holderName: string;
}

export interface ClientNote {
  id: string;
  clientId: string;
  content: string;
  date: string;
  createdBy: string;
}

export interface ClientDocument {
  id: string;
  clientId: string;
  title: string; // e.g., "Cédula Frontal", "Contrato Firmado"
  type: 'Cedula' | 'Contrato' | 'Garantia' | 'Otro';
  fileUrl: string; // In a real app, this is an S3 URL. Here we can use mock images or data URIs.
  fileType: string; // mime type e.g., 'image/jpeg', 'application/pdf'
  uploadDate: string;
}

export interface Loan {
  id: string;
  clientId: string;
  clientName: string;
  amount: number;
  interestRate: number; // Percentage (e.g., 10 for 10%)
  durationWeeks: number;
  frequency: 'Semanal' | 'Quincenal' | 'Mensual' | 'Diario';
  startDate: string;
  status: LoanStatus;
  totalToPay: number;
  remainingBalance: number;
  nextPaymentDate: string;
  // New Collateral Fields
  collateralType?: 'Vehículo' | 'Propiedad' | 'Electrodoméstico' | 'Sin Garantía';
  collateralDescription?: string; // e.g., "Toyota Camry 2015"
  collateralRef?: string; // e.g., "Matrícula: AB-123456"
}

export interface Transaction {
  id: string;
  type: 'Ingreso' | 'Gasto';
  category: 'Pago Préstamo' | 'Desembolso' | 'Operativo' | 'Nómina' | 'Capital' | 'Otro';
  amount: number;
  date: string;
  description: string;
  referenceId?: string; // ID of loan or client related
}

export interface Employee {
  id: string;
  name: string;
  role: 'Admin' | 'Collector' | 'Secretary';
  performance: number; // 0-100
  activeRoutes: number;
}

export interface InvoiceItem {
  id: string;
  description: string;
  quantity: number;
  unitPrice: number;
  subtotal: number;
}

export interface Invoice {
  id: string;
  date: string;
  reference: string;
  clientName: string;
  status: 'Emitida' | 'Anulada' | 'Completada';
  paymentStatus: 'Pagado' | 'Pendiente' | 'Parcial';
  items: InvoiceItem[];
  subtotal: number;
  total: number;
  totalPaid: number;
  totalPending: number;
  seller: string;
  createdBy: string;
  updatedBy: string;
  updatedAt: string;
  warrantyInfo: string;
}

// --- Auth & Settings Types ---

export type Permission = 'manage_loans' | 'manage_clients' | 'manage_users' | 'view_reports' | 'manage_settings' | 'approve_loans';

export interface Role {
  id: string;
  name: string;
  description: string;
  permissions: Permission[];
}

export interface User {
  id: string;
  name: string;
  email?: string; // Made optional
  username?: string; // Added for non-email logins
  password?: string; // In real app, this is hashed. keeping simple for mock.
  roleId: string;
  avatarUrl?: string;
  status: 'Active' | 'Inactive';
}

export interface CompanySettings {
  name: string;
  rnc: string; // Tax ID
  address: string;
  phone: string;
  email: string;
  website?: string;
  logoUrl?: string; // URL for the logo
  currency: string;
  termsAndConditions: string;
}

export interface AuditLog {
  id: string;
  userId: string;
  userName: string;
  action: string; // e.g., "Created Loan", "Deleted User"
  details: string; // JSON string or description
  timestamp: string;
  ipAddress?: string;
}

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { Client, Loan, Transaction, LoanStatus, BankAccount, ClientNote, ClientDocument, User, Role, CompanySettings, AuditLog } from '../types';

interface StoreContextType {
  // Data
  clients: Client[];
  loans: Loan[];
  transactions: Transaction[];
  bankAccounts: BankAccount[];
  clientNotes: ClientNote[];
  clientDocuments: ClientDocument[];
  auditLogs: AuditLog[];

  // Auth & System
  currentUser: User | null;
  users: User[];
  roles: Role[];
  companySettings: CompanySettings;

  // Actions
  login: (identifier: string, password: string) => boolean;
  logout: () => void;
  registerUser: (user: User) => void;
  updateUser: (user: User) => void;
  updateCompanySettings: (settings: CompanySettings) => void;
  addRole: (role: Role) => void;
  deleteRole: (id: string) => void;

  // Domain Actions
  addClient: (client: Client) => void;
  updateClient: (client: Client) => void;
  createLoan: (loanData: Omit<Loan, 'id' | 'status' | 'remainingBalance' | 'totalToPay'>) => void;
  refinanceLoan: (oldLoanId: string, newLoanData: Omit<Loan, 'id' | 'status' | 'remainingBalance' | 'totalToPay'>) => void;
  registerPayment: (loanId: string, amount: number, note: string) => void;
  addBankAccount: (account: BankAccount) => void;
  removeBankAccount: (id: string) => void;
  addClientNote: (note: ClientNote) => void;
  addClientDocument: (doc: ClientDocument) => void;
  removeClientDocument: (id: string) => void;
  getFinancialStats: () => { balance: number; incomeToday: number; expenseToday: number };
}

const StoreContext = createContext<StoreContextType | undefined>(undefined);

