                              <span className="text-sm font-medium text-indigo-700">Total Contado</span>
                              <span className="font-bold text-2xl text-indigo-800">${countedTotal.toLocaleString()}</span>
                          </div>

                          {difference !== 0 && (
                              <div className={`flex justify-between items-center p-4 rounded-2xl border ${difference > 0 ? 'bg-emerald-50 border-emerald-100 text-emerald-700' : 'bg-rose-50 border-rose-100 text-rose-700'}`}>
                                  <span className="flex items-center gap-2 font-bold">
                                      <AlertTriangle className="w-5 h-5" /> 
                                      {difference > 0 ? 'Sobrante' : 'Faltante'}
                                  </span>
                                  <span className="font-bold text-xl">{difference > 0 ? '+' : ''}{difference.toLocaleString()}</span>
                              </div>
                          )}

                          <div className="mt-6">
                              <label className="block text-sm font-bold text-slate-700 mb-2">Nota de Cierre</label>
                              <textarea 
                                className="w-full border border-slate-200 bg-slate-50 rounded-xl p-3 text-sm focus:ring-2 focus:ring-indigo-500 outline-none" 
                                rows={4}
                                placeholder="Observaciones sobre el cuadre..."
                                value={closingData.notes}
                                onChange={e => setClosingData({...closingData, notes: e.target.value})}
                              ></textarea>
                          </div>
                      </div>
                  </div>

                  <button 
                    onClick={() => alert("Cierre de caja guardado con éxito.")}
                    className="w-full bg-gradient-to-r from-slate-900 to-slate-800 text-white py-4 rounded-xl font-bold hover:shadow-lg hover:shadow-slate-500/20 mt-8 flex items-center justify-center gap-2 transition-all transform hover:-translate-y-0.5"
                  >
                      <Save className="w-5 h-5" /> Cerrar Caja del Día
                  </button>
              </div>
          </div>
      )}
    </div>
  );
};

