               <button onClick={() => navigate('/clientes')} className="p-3 bg-white border border-slate-100 shadow-sm hover:shadow-md rounded-full transition-all">
                  <ArrowLeft className="w-5 h-5 text-slate-600" />
               </button>
               <div>
                  <h1 className="text-2xl font-bold text-slate-800">{client.name}</h1>
                  <p className="text-slate-500 text-sm flex items-center gap-2">
                    <span className="font-mono bg-slate-100 px-1.5 py-0.5 rounded text-xs">ID: {client.id}</span> 
                    <span className="w-1.5 h-1.5 bg-slate-300 rounded-full"></span> 
                    <span className={`text-xs font-bold ${client.status === 'Activo' ? 'text-emerald-500' : 'text-rose-500'}`}>{client.status}</span>
                  </p>
