                <div className="w-24 h-24 rounded-2xl bg-white p-1 shadow-lg shadow-slate-200/50 rotate-3 transform">
                    <div className="w-full h-full bg-slate-100 rounded-xl flex items-center justify-center text-3xl font-bold text-slate-400 border border-slate-200">
                        {client.name.charAt(0)}
                    </div>
                </div>

                <div className="flex-1 w-full md:w-auto flex flex-col md:flex-row justify-between items-center md:items-end gap-4">
                    <div>
                        <h2 className="text-xl font-bold text-slate-800">{client.name}</h2>
                        <p className="text-slate-500 text-sm flex items-center gap-2">
                           <MapPin className="w-4 h-4" /> {client.address}
