                        </div>
                    </div>
                )) : (
                    <div className="text-center py-10 text-slate-400 bg-slate-50 rounded-2xl border border-dashed border-slate-200">
                        <Banknote className="w-10 h-10 mx-auto mb-3 opacity-30" />
                        <p>No hay préstamos registrados.</p>
                    </div>
                )}
