                             <button 
                                onClick={(e) => { e.stopPropagation(); removeClientDocument(doc.id); }}
                                className="absolute top-2 right-2 p-1.5 text-slate-400 hover:text-rose-500 hover:bg-white rounded-full opacity-0 group-hover:opacity-100 transition-all shadow-sm"
                             >
                                 <Trash2 className="w-4 h-4" />
                             </button>
                             <div className="w-16 h-16 bg-white rounded-2xl flex items-center justify-center shadow-sm group-hover:scale-110 transition-transform">
                                 {getDocIcon(doc.type, doc.fileType)}
                             </div>
                             <div className="text-center w-full">
                                 <p className="font-bold text-slate-700 text-xs truncate w-full mb-1">{doc.title}</p>
                                 <span className={`text-[10px] px-2 py-0.5 rounded-full font-bold ${doc.type === 'Cedula' ? 'bg-blue-100 text-blue-600' : 'bg-slate-200 text-slate-500'}`}>{doc.type}</span>
                             </div>
                         </div>
                     ))}
                 </div>
            </div>
        )}

        {activeTab === 'banks' && (
            <div>
                 <div className="flex justify-between items-center mb-6">
                     <h3 className="font-bold text-slate-800 text-lg">Cuentas Bancarias</h3>
                     <button onClick={() => setShowBankForm(!showBankForm)} className="text-sm bg-indigo-50 text-indigo-600 px-4 py-2 rounded-xl font-bold hover:bg-indigo-100 transition-colors flex items-center gap-2">
                         <Plus className="w-4 h-4" /> Nueva Cuenta
                     </button>
                 </div>

                 {showBankForm && (
                     <form onSubmit={handleAddBank} className="mb-8 bg-slate-50 p-6 rounded-2xl border border-slate-200 animate-fade-in">
