                             <input type="text" placeholder="Banco (Ej. Popular)" className="px-4 py-3 rounded-xl border focus:ring-2 focus:ring-indigo-500 outline-none" value={newBank.bankName} onChange={e => setNewBank({...newBank, bankName: e.target.value})} required />
                             <input type="text" placeholder="No. Cuenta" className="px-4 py-3 rounded-xl border focus:ring-2 focus:ring-indigo-500 outline-none" value={newBank.accountNumber} onChange={e => setNewBank({...newBank, accountNumber: e.target.value})} required />
                             <input type="text" placeholder="Titular de la cuenta" className="px-4 py-3 rounded-xl border focus:ring-2 focus:ring-indigo-500 outline-none" value={newBank.holderName} onChange={e => setNewBank({...newBank, holderName: e.target.value})} />
                             <select className="px-4 py-3 rounded-xl border bg-white focus:ring-2 focus:ring-indigo-500 outline-none" value={newBank.accountType} onChange={e => setNewBank({...newBank, accountType: e.target.value as any})}>
                                 <option>Ahorro</option>
                                 <option>Corriente</option>
                             </select>
