                                 </div>
                                 <div>
                                     <h4 className="font-bold text-slate-800">{bank.bankName}</h4>
                                     <p className="text-sm text-slate-500 font-mono tracking-wide">{bank.accountNumber}</p>
                                     <span className="text-xs text-slate-400">{bank.accountType}</span>
                                 </div>
                             </div>
                             <button onClick={() => removeBankAccount(bank.id)} className="text-slate-300 hover:text-rose-500 hover:bg-rose-50 p-2 rounded-lg transition-colors"><Trash2 className="w-5 h-5" /></button>
