            </div>
        )}

        {activeTab === 'notes' && (
            <div>
                 <div className="mb-8">
                     <textarea 
                        className="w-full border border-slate-200 bg-slate-50 rounded-2xl p-4 focus:ring-2 focus:ring-indigo-500 outline-none resize-none transition-all focus:bg-white"
