                     <div className="flex justify-end mt-3">
                         <button onClick={handleAddNote} className="bg-indigo-600 text-white px-6 py-2 rounded-xl text-sm font-bold hover:bg-indigo-700 shadow-lg shadow-indigo-500/20">Agregar Nota</button>
                     </div>
                 </div>
                 <div className="space-y-4">
                     {myNotes.map(note => (
                         <div key={note.id} className="bg-amber-50/50 p-5 rounded-2xl border border-amber-100">
                             <p className="text-slate-800 text-sm mb-3 leading-relaxed">{note.content}</p>
                             <div className="flex justify-between items-center text-xs text-amber-600/60 font-medium">
                                 <span className="flex items-center gap-1"><Clock className="w-3 h-3" /> {note.date}</span>
                                 <span>Autor: {note.createdBy}</span>
