                             <option value="Contrato">Contrato Firmado</option>
                             <option value="Garantia">Garantía / Aval</option>
                             <option value="Otro">Otro</option>
                         </select>
                     </div>
                     <div className="border-2 border-dashed border-slate-200 rounded-2xl p-8 text-center hover:bg-slate-50 transition-colors cursor-pointer relative group">
                         <input type="file" className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10" onChange={handleFileChange} accept="image/*,.pdf" />
                         {selectedFile ? (
                             <div className="flex flex-col items-center">
                                 <FileCheck className="w-10 h-10 text-emerald-500 mb-3" />
                                 <span className="text-sm font-bold text-slate-700">{selectedFile.name}</span>
