                             <label className="block text-sm font-bold text-slate-700 mb-1">Ingresos</label>
                             <input type="number" className="w-full px-4 py-2 border rounded-xl" value={editFormData.income} onChange={e => setEditFormData({...editFormData, income: Number(e.target.value)})} />
