                            {loanType === 'Amortizado' && calcMode === 'installment' && (
                                <div className="bg-white/10 p-3 rounded-lg text-center backdrop-blur-sm">
                                    <span className="block text-indigo-200 text-xs mb-1">Duración Calculada</span>
