import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { Client, Loan, Transaction, LoanStatus, BankAccount, ClientNote, ClientDocument, User, Role, CompanySettings, AuditLog } from '../types';

interface StoreContextType {
  // Data
  clients: Client[];
  loans: Loan[];
