  // Domain State
  const [clients, setClients] = useState<Client[]>(initialClients);
  const [loans, setLoans] = useState<Loan[]>(initialLoans);
  const [loanRequests, setLoanRequests] = useState<LoanRequest[]>(initialRequests);
  const [transactions, setTransactions] = useState<Transaction[]>(initialTransactions);
  const [bankAccounts, setBankAccounts] = useState<BankAccount[]>(initialBanks);
  const [clientNotes, setClientNotes] = useState<ClientNote[]>(initialNotes);
  const [clientDocuments, setClientDocuments] = useState<ClientDocument[]>(initialDocuments);
  const [auditLogs, setAuditLogs] = useState<AuditLog[]>(initialAuditLogs);

  // Auth & System State
  const [users, setUsers] = useState<User[]>(initialUsers);
  const [roles, setRoles] = useState<Role[]>(initialRoles);
  const [companySettings, setCompanySettings] = useState<CompanySettings>(initialCompanySettings);

  // Persist login simulation
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('currentUser');
    return saved ? JSON.parse(saved) : null;
  });

  // --- Helper for Logging ---
  const logAction = (action: string, details: string) => {
      const newLog: AuditLog = {
          id: `LOG-${Date.now()}`,
          userId: currentUser?.id || 'system',
          userName: currentUser?.name || 'System',
          action,
          details,
          timestamp: new Date().toISOString()
      };
      setAuditLogs(prev => [newLog, ...prev]);
  };

  // --- Auth Actions ---

  const login = (identifier: string, password: string): boolean => {
    // Check against email OR username
    const user = users.find(u => 
      (u.email === identifier || u.username === identifier) && u.password === password
    );

    if (user) {
      setCurrentUser(user);
      localStorage.setItem('currentUser', JSON.stringify(user));
      return true;
    }
    return false;
  };

  const logout = () => {
    logAction('Logout', 'Cierre de sesión');
    setCurrentUser(null);
    localStorage.removeItem('currentUser');
  };

  const registerUser = (user: User) => {
    setUsers(prev => [...prev, user]);
    logAction('Register User', `Nuevo usuario registrado: ${user.name} (${user.roleId})`);
  };

  const updateUser = (updatedUser: User) => {
    setUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
    if (currentUser && currentUser.id === updatedUser.id) {
        setCurrentUser(updatedUser);
        localStorage.setItem('currentUser', JSON.stringify(updatedUser));
    }
    logAction('Update User', `Perfil actualizado: ${updatedUser.name}`);
  };

  const updateCompanySettings = (settings: CompanySettings) => {
    setCompanySettings(settings);
    logAction('Update Settings', 'Actualización de configuración de empresa');
  };

  const addRole = (role: Role) => {
    setRoles(prev => [...prev, role]);
    logAction('Add Role', `Creación de rol: ${role.name}`);
  };

  const deleteRole = (id: string) => {
    setRoles(prev => prev.filter(r => r.id !== id));
    logAction('Delete Role', `Eliminación de rol ID: ${id}`);
  };

  // --- Domain Actions ---

  const addClient = (client: Client) => {
    setClients(prev => [client, ...prev]);
    logAction('Create Client', `Cliente creado: ${client.name} - ${client.cedula}`);
  };

  const updateClient = (updatedClient: Client) => {
    setClients(prev => prev.map(c => c.id === updatedClient.id ? updatedClient : c));
    logAction('Update Client', `Cliente actualizado: ${updatedClient.name}`);
  };

  // --- LOAN REQUEST LOGIC ---

  const addLoanRequest = (request: Omit<LoanRequest, 'id' | 'status' | 'requestDate'>) => {
      const newRequest: LoanRequest = {
          ...request,
          id: `REQ-${Math.floor(1000 + Math.random() * 9000)}`,
          status: 'Pendiente',
          requestDate: new Date().toISOString().split('T')[0]
      };
      setLoanRequests(prev => [newRequest, ...prev]);
      logAction('Create Request', `Solicitud creada para ${request.clientName}: $${request.amount}`);
  };

  const deleteLoanRequest = (requestId: string) => {
      setLoanRequests(prev => prev.filter(r => r.id !== requestId));
      logAction('Remove Request', `Solicitud eliminada/procesada: ${requestId}`);
  };

  const createLoan = (loanData: Omit<Loan, 'id' | 'status' | 'remainingBalance' | 'totalToPay'>) => {
    // 1. Determine Actual Principal based on Closing Cost Mode
    let finalPrincipal = loanData.amount;
    const closingCost = loanData.closingCost || 0;

    if (loanData.closingCostMode === 'Financiado') {
        finalPrincipal += closingCost;
    }

    // 2. Calculate Total Debt
    let totalToPay = 0;
    let initialBalance = 0;

    if (loanData.loanType === 'Amortizado') {
        const totalInterest = finalPrincipal * (loanData.interestRate / 100);
        totalToPay = finalPrincipal + totalInterest;
        initialBalance = totalToPay;
    } else {
        totalToPay = finalPrincipal;
        initialBalance = finalPrincipal;
    }

    // 3. Date Logic for specific Payment Day (Override if passed in loanData)
    let nextPaymentDate = loanData.nextPaymentDate;
    if (loanData.frequency === 'Mensual' && loanData.paymentDay && !nextPaymentDate) {
         const d = new Date();
         if (d.getDate() >= loanData.paymentDay) {
             d.setMonth(d.getMonth() + 1);
         }
         d.setDate(loanData.paymentDay);
         nextPaymentDate = d.toISOString().split('T')[0];
    } else if (!nextPaymentDate) {
         const d = new Date();
         d.setDate(d.getDate() + 7);
         nextPaymentDate = d.toISOString().split('T')[0];
    }

    const newLoan: Loan = {
      ...loanData,
      amount: finalPrincipal, 
      id: `LN-${Math.floor(1000 + Math.random() * 9000)}`,
      status: LoanStatus.ACTIVE,
      totalToPay,
      remainingBalance: initialBalance,
      nextPaymentDate
    };

    setLoans(prev => [newLoan, ...prev]);

    // 4. Create Transactions based on Closing Cost Mode
    let disbursementAmount = loanData.amount;
    if (loanData.closingCostMode === 'Descontado') {
        disbursementAmount = loanData.amount - closingCost;
    }

    const transactionId = `TRX-${Math.floor(Date.now() / 1000)}`;
    const disbursalTransaction: Transaction = {
      id: transactionId,
      type: 'Gasto',
      category: 'Desembolso',
      amount: disbursementAmount,
      date: new Date().toISOString().split('T')[0],
      description: `Desembolso ${newLoan.loanType} para ${loanData.clientName}`,
      referenceId: newLoan.id
    };
    setTransactions(prev => [disbursalTransaction, ...prev]);

    if (loanData.closingCostMode === 'Externo' && closingCost > 0) {
        const feeTransaction: Transaction = {
            id: `TRX-FEE-${Math.floor(Date.now() / 1000)}`,
            type: 'Ingreso',
            category: 'Cierre',
            amount: closingCost,
            date: new Date().toISOString().split('T')[0],
            description: `Cobro Gastos de Cierre - ${loanData.clientName}`,
            referenceId: newLoan.id
        };
        setTransactions(prev => [feeTransaction, ...prev]);
    }

    // 5. AUTO-GENERATE CONTRACT
    const contractDoc: ClientDocument = {
        id: `DOC-CONT-${Date.now()}`,
        clientId: loanData.clientId,
        title: `Contrato Préstamo ${newLoan.id}`,
        type: 'Contrato',
        fileUrl: '', // In real app, this would be a generated PDF URL
        fileType: 'application/pdf',
        uploadDate: new Date().toISOString().split('T')[0]
    };
    setClientDocuments(prev => [contractDoc, ...prev]);

    logAction('Create Loan', `Préstamo ${newLoan.loanType} desembolsado ${newLoan.id} con Contrato generado.`);
  };

  const refinanceLoan = (oldLoanId: string, newLoanData: Omit<Loan, 'id' | 'status' | 'remainingBalance' | 'totalToPay'>) => {
    let oldBalance = 0;
    setLoans(prev => prev.map(l => {
        if (l.id === oldLoanId) {
            oldBalance = l.remainingBalance;
            return { ...l, remainingBalance: 0, status: LoanStatus.PAID };
        }
        return l;
    }));

    createLoan(newLoanData);

    const transaction: Transaction = {
        id: `TRX-REF-${Math.floor(Date.now() / 1000)}`,
        type: 'Ingreso',
        category: 'Pago Préstamo',
        amount: oldBalance,
        date: new Date().toISOString().split('T')[0],
        description: `Refinanciamiento: Cancelación Saldo ${oldLoanId}`,
        referenceId: oldLoanId
    };
    setTransactions(prev => [transaction, ...prev]);
    logAction('Refinance Loan', `Refinanciamiento de ${oldLoanId}. Nuevo monto: $${newLoanData.amount}`);
  };

  const registerPayment = (loanId: string, amount: number, note: string) => {
    setLoans(prevLoans => prevLoans.map(loan => {
      if (loan.id === loanId) {
        const newBalance = Math.max(0, loan.remainingBalance - amount);
        const newStatus = newBalance === 0 ? LoanStatus.PAID : LoanStatus.ACTIVE;
        return { ...loan, remainingBalance: newBalance, status: newStatus };
      }
      return loan;
    }));

    const loan = loans.find(l => l.id === loanId);
    const transaction: Transaction = {
      id: `TRX-${Math.floor(Date.now() / 1000)}`,
      type: 'Ingreso',
      category: 'Pago Préstamo',
      amount: amount,
      date: new Date().toISOString().split('T')[0],
      description: `Pago: ${note} - ${loan?.clientName}`,
      referenceId: loanId
    };
    setTransactions(prev => [transaction, ...prev]);
    logAction('Register Payment', `Pago registrado: $${amount} para préstamo ${loanId} (${note})`);
  };

  const addBankAccount = (account: BankAccount) => {
    setBankAccounts(prev => [...prev, account]);
    logAction('Add Bank', `Cuenta bancaria agregada para cliente ${account.clientId}`);
  };

  const removeBankAccount = (id: string) => {
    setBankAccounts(prev => prev.filter(b => b.id !== id));
    logAction('Remove Bank', `Cuenta bancaria eliminada ID: ${id}`);
  };

  const addClientNote = (note: ClientNote) => {
    setClientNotes(prev => [note, ...prev]);
    logAction('Add Note', `Nota agregada a cliente ${note.clientId}`);
  };

  const addClientDocument = (doc: ClientDocument) => {
      setClientDocuments(prev => [doc, ...prev]);
      logAction('Upload Document', `Documento subido para cliente ${doc.clientId}: ${doc.title}`);
  };

  const removeClientDocument = (id: string) => {
      setClientDocuments(prev => prev.filter(d => d.id !== id));
      logAction('Delete Document', `Documento eliminado ID: ${id}`);
  };

  const getFinancialStats = () => {
    const today = new Date().toISOString().split('T')[0];

    const balance = transactions.reduce((acc, curr) => {
      return curr.type === 'Ingreso' ? acc + curr.amount : acc - curr.amount;
    }, 0);

    const incomeToday = transactions
      .filter(t => t.date === today && t.type === 'Ingreso')
      .reduce((sum, t) => sum + t.amount, 0);

    const expenseToday = transactions
      .filter(t => t.date === today && t.type === 'Gasto')
      .reduce((sum, t) => sum + t.amount, 0);

    return { balance, incomeToday, expenseToday };
  };

  return (
    <StoreContext.Provider value={{ 
      clients, loans, loanRequests, transactions, bankAccounts, clientNotes, clientDocuments, auditLogs,
      currentUser, users, roles, companySettings,
      login, logout, registerUser, updateUser, updateCompanySettings, addRole, deleteRole,
      addClient, updateClient, 
      addLoanRequest, deleteLoanRequest, createLoan, 
      refinanceLoan, registerPayment, 
      addBankAccount, removeBankAccount, addClientNote,
      addClientDocument, removeClientDocument,
      getFinancialStats 
    }}>
      {children}
    </StoreContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(StoreContext);
  if (context === undefined) {
    throw new Error('useStore must be used within a StoreProvider');
  }
  return context;
};

import React, { useState, useEffect } from 'react';
import { Calculator, Save, User, Plus, Search, Filter, ArrowRight, ChevronLeft, Clock, Banknote, Briefcase, FileCheck, RefreshCw, Scissors, Coins, ExternalLink, Calendar, CheckCircle, XCircle } from 'lucide-react';
import { useStore } from '../context/StoreContext';
import { useNavigate } from 'react-router-dom';
import { LoanType, ClosingCostMode, LoanRequest as ILoanRequest } from '../types';

const LoanRequest: React.FC = () => {
  const { clients, createLoan, addLoanRequest, loanRequests, deleteLoanRequest } = useStore();
  const navigate = useNavigate();

  // View State
  const [viewMode, setViewMode] = useState<'create' | 'queue'>('queue');
  const [creationMode, setCreationMode] = useState<'request' | 'direct'>('request'); // 'request' = Solicitud, 'direct' = Loan

  // Track if we are processing a pending request (to delete it later)
  const [processingRequestId, setProcessingRequestId] = useState<string | null>(null);

  // Form State
  const [selectedClientId, setSelectedClientId] = useState('');
  const [amount, setAmount] = useState(10000);
  const [weeks, setWeeks] = useState(12); // Duración
  const [interest, setInterest] = useState(10); // Porcentaje
  const [frequency, setFrequency] = useState('Semanal');
  const [paymentDay, setPaymentDay] = useState(1); // For Monthly Loans
  const [loanType, setLoanType] = useState<LoanType>('Amortizado');

  // Closing Costs State
  const [closingCost, setClosingCost] = useState(0);
  const [closingCostMode, setClosingCostMode] = useState<ClosingCostMode>('Descontado');

  // New: Calculation Mode (Time vs Amount)
  const [calcMode, setCalcMode] = useState<'time' | 'installment'>('time');
  const [targetInstallment, setTargetInstallment] = useState(1000);

  const selectedClient = clients.find(c => c.id === selectedClientId);

  // --- Core Calculation Logic ---

  const getPrincipalForCalculation = () => {
      // If "Financiado", the principal increases by the closing cost
      if (closingCostMode === 'Financiado') {
          return amount + closingCost;
      }
      return amount;
  };

  // Efecto para recalcular cuando cambian los inputs
  useEffect(() => {
    if (loanType === 'Amortizado' && calcMode === 'installment') {
        const principal = getPrincipalForCalculation();
        const totalDebt = principal * (1 + (interest / 100));
        if (targetInstallment > 0) {
            const calculatedWeeks = Math.ceil(totalDebt / targetInstallment);
            setWeeks(calculatedWeeks > 0 ? calculatedWeeks : 1);
        }
    }
  }, [amount, interest, targetInstallment, calcMode, loanType, closingCost, closingCostMode]);

  const calculateTotal = () => {
    const principal = getPrincipalForCalculation();
    if (loanType === 'Amortizado') {
        const totalInterest = principal * (interest / 100);
        return principal + totalInterest;
    } else {
        return principal; 
    }
  };

  const calculateInstallment = () => {
    const principal = getPrincipalForCalculation();
    if (loanType === 'Amortizado') {
        if (calcMode === 'installment') return targetInstallment; 
        return calculateTotal() / weeks; 
    } else {
        return principal * (interest / 100);
    }
  };

  const getNetDisbursement = () => {
      if (closingCostMode === 'Descontado') {
          return amount - closingCost;
      }
      return amount;
  };

  const handleProcessRequest = (req: ILoanRequest) => {
      // Load data into form
      setSelectedClientId(req.clientId);
      setAmount(req.amount);
      setInterest(req.interestRate);
      setWeeks(req.durationWeeks);
      setFrequency(req.frequency);
      setLoanType(req.loanType);
      if (req.closingCost) setClosingCost(req.closingCost);
      if (req.closingCostMode) setClosingCostMode(req.closingCostMode);
      if (req.paymentDay) setPaymentDay(req.paymentDay);

      // Set UI state to Creation Mode (Direct)
      setProcessingRequestId(req.id);
      setCreationMode('direct');
      setViewMode('create');
  };

  const handleSubmit = () => {
    if (!selectedClient) {
        alert("Por favor seleccione un cliente");
        return;
    }

    const finalWeeks = loanType === 'Rédito' ? 0 : weeks;
    // Calculate initial next payment date based on paymentDay (if direct loan + monthly)
    let initialNextDate = new Date();
    initialNextDate.setDate(initialNextDate.getDate() + 7); // Default fallback

    if (frequency === 'Mensual') {
        const today = new Date();
        if (today.getDate() >= paymentDay) {
            initialNextDate = new Date(today.getFullYear(), today.getMonth() + 1, paymentDay);
        } else {
            initialNextDate = new Date(today.getFullYear(), today.getMonth(), paymentDay);
        }
    }

    if (creationMode === 'direct') {
        createLoan({
            clientId: selectedClient.id,
            clientName: selectedClient.name,
            amount,
            interestRate: interest,
            durationWeeks: finalWeeks,
            frequency: frequency as any,
            loanType,
            closingCost,
            closingCostMode,
            paymentDay: frequency === 'Mensual' ? paymentDay : undefined,
            startDate: new Date().toISOString().split('T')[0],
            nextPaymentDate: initialNextDate.toISOString().split('T')[0]
        });

        // If this came from a request, delete the request now that it is a loan
        if (processingRequestId) {
            deleteLoanRequest(processingRequestId);
            setProcessingRequestId(null);
        }

        navigate('/prestamos');
    } else {
        addLoanRequest({
            clientId: selectedClient.id,
            clientName: selectedClient.name,
            amount,
            interestRate: interest,
            durationWeeks: finalWeeks,
            frequency: frequency as any,
            loanType,
            closingCost,
            closingCostMode,
            paymentDay: frequency === 'Mensual' ? paymentDay : undefined
        });
        alert("Solicitud guardada con éxito.");
        setViewMode('queue');
    }
  };

  if (viewMode === 'create') {
    return (
        <div className="max-w-5xl mx-auto animate-fade-in space-y-6 pb-10">
            <div className="flex items-center gap-4">
                <button onClick={() => { setViewMode('queue'); setProcessingRequestId(null); }} className="p-2 hover:bg-slate-200 rounded-full transition-colors">
                    <ChevronLeft className="w-6 h-6 text-slate-600" />
                </button>
                <div>
                    <h2 className="text-2xl font-bold text-slate-800">Nueva {creationMode === 'request' ? 'Solicitud' : 'Concesión'}</h2>
                    <p className="text-slate-500">Configuración del préstamo y plan de pagos.</p>
                </div>
            </div>

            {/* Mode Toggle */}
            <div className="bg-white p-2 rounded-xl inline-flex border border-slate-200 shadow-sm">
                <button 
                    onClick={() => setCreationMode('request')}
                    className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${creationMode === 'request' ? 'bg-indigo-600 text-white' : 'text-slate-500 hover:bg-slate-50'}`}
                >
                    Crear Solicitud (Revisión)
                </button>
                <button 
                    onClick={() => setCreationMode('direct')}
                    className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${creationMode === 'direct' ? 'bg-emerald-600 text-white' : 'text-slate-500 hover:bg-slate-50'}`}
                >
                    Desembolso Directo
                </button>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                <div className="lg:col-span-2 space-y-6">
                    {/* Client Selection */}
                    <div className="bg-white rounded-3xl shadow-sm border border-slate-100 p-8">
                        <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2">
                        <div className="p-2 bg-indigo-50 text-indigo-600 rounded-lg"><User className="w-5 h-5" /></div>
                        Información del Cliente
                        </h3>
                        <div className="grid grid-cols-1 gap-4">
                        <div>
                            <label className="block text-sm font-bold text-slate-700 mb-2">Seleccionar Cliente</label>
                            <select 
                                className="w-full px-4 py-3 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-indigo-500 text-sm bg-slate-50"
                                value={selectedClientId}
                                onChange={(e) => setSelectedClientId(e.target.value)}
                            >
                                <option value="">-- Buscar Cliente --</option>
                                {clients.map(client => (
                                    <option key={client.id} value={client.id}>{client.name} - {client.cedula}</option>
                                ))}
                            </select>
                        </div>
                        </div>
                    </div>

                    {/* Financial Config */}
                    <div className="bg-white rounded-3xl shadow-sm border border-slate-100 p-8">
                        <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2">
                        <div className="p-2 bg-emerald-50 text-emerald-600 rounded-lg"><Calculator className="w-5 h-5" /></div>
                        Configuración Financiera
                        </h3>

                        {/* Loan Type Selector */}
                        <div className="mb-6 grid grid-cols-2 gap-4">
                            <div 
                                onClick={() => { setLoanType('Amortizado'); setCalcMode('time'); }}
                                className={`cursor-pointer border rounded-2xl p-4 flex flex-col gap-2 transition-all ${loanType === 'Amortizado' ? 'border-indigo-500 bg-indigo-50 text-indigo-700 ring-1 ring-indigo-500' : 'border-slate-200 hover:border-slate-300'}`}
                            >
                                <div className="flex justify-between">
                                    <span className="font-bold text-sm">Cuotas Fijas (Amortizado)</span>
                                    {loanType === 'Amortizado' && <FileCheck className="w-5 h-5 text-indigo-600" />}
                                </div>
                                <span className="text-xs opacity-70">Capital + Interés dividido en pagos</span>
                            </div>
                            <div 
                                onClick={() => { setLoanType('Rédito'); setCalcMode('time'); }}
                                className={`cursor-pointer border rounded-2xl p-4 flex flex-col gap-2 transition-all ${loanType === 'Rédito' ? 'border-purple-500 bg-purple-50 text-purple-700 ring-1 ring-purple-500' : 'border-slate-200 hover:border-slate-300'}`}
                            >
                                <div className="flex justify-between">
                                    <span className="font-bold text-sm">Pagaré Abierto (Rédito)</span>
                                    {loanType === 'Rédito' && <FileCheck className="w-5 h-5 text-purple-600" />}
                                </div>
                                <span className="text-xs opacity-70">Solo paga interés. Capital al final.</span>
                            </div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            {/* Monto */}
                            <div className="md:col-span-2">
                                <label className="block text-sm font-bold text-slate-700 mb-2">Monto a Prestar (Capital)</label>
                                <div className="relative">
                                <span className="absolute left-4 top-3 text-slate-400 font-bold">$</span>
                                <input 
