          totalToPay = amount; // Principal to pay at end
          installment = interestAmount; // Periodic payment is just interest
      }

      setResult({
          installment,
          total: totalToPay,
          totalInterest: type === 'Amortizado' ? (amount * (interest/100)) : (amount * (interest/100)) * weeks // Projected for Rédito
