import StatCard from '../components/StatCard';
import { useStore } from '../context/StoreContext';
import { useNavigate } from 'react-router-dom';

const Profit: React.FC = () => {
  const { transactions, loans } = useStore();
  const navigate = useNavigate();

  // Financial Calculations
  const totalIncome = transactions
    .filter(t => t.type === 'Ingreso' && t.category !== 'Capital') // Exclude capital injections
    .reduce((sum, t) => sum + t.amount, 0);

  const totalExpenses = transactions
    .filter(t => t.type === 'Gasto' && t.category !== 'Desembolso') // Operational expenses only, excluding loan disbursements
    .reduce((sum, t) => sum + t.amount, 0);

  const netProfit = totalIncome - totalExpenses;

  // Potential Interest (Projected)
  const projectedInterest = loans.reduce((sum, loan) => {
    return sum + (loan.totalToPay - loan.amount);
  }, 0);

  // Mock Data for Charts
  const profitData = [
    { name: 'Sem 1', ingresos: 12000, gastos: 4000 },
    { name: 'Sem 2', ingresos: 15000, gastos: 3500 },
    { name: 'Sem 3', ingresos: 11000, gastos: 5000 },
    { name: 'Sem 4', ingresos: 18000, gastos: 4200 },
  ];

  return (
    <div className="space-y-8 animate-fade-in pb-10">
      <div className="flex justify-between items-center">
        <div className="flex items-center gap-3">
            <button onClick={() => navigate(-1)} className="p-2 hover:bg-slate-200 rounded-full transition-colors">
                <ChevronLeft className="w-5 h-5 text-slate-600" />
            </button>
            <div>
              <h2 className="text-2xl font-bold text-slate-800">Reporte de Ganancias</h2>
              <p className="text-slate-500">Análisis de rentabilidad operativa y neta.</p>
