                <div className="space-y-5">
                    {[
                        { label: 'Intereses Préstamos', val: 85, color: 'bg-emerald-500' },
                        { label: 'Cargos por Mora', val: 12, color: 'bg-amber-500' },
                        { label: 'Comisiones', val: 3, color: 'bg-indigo-500' }
                    ].map((item, idx) => (
