export const StoreProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const { addToast } = useToast();

  // Domain State with Persistence
  const [clients, setClients] = usePersistedState<Client[]>('clients', initialClients);
  const [loans, setLoans] = usePersistedState<Loan[]>('loans', initialLoans);
  const [employees, setEmployees] = usePersistedState<Employee[]>('employees', initialEmployees);
  const [loanRequests, setLoanRequests] = usePersistedState<LoanRequest[]>('loanRequests', initialLoanRequests);
  const [transactions, setTransactions] = usePersistedState<Transaction[]>('transactions', initialTransactions);
  const [bankAccounts, setBankAccounts] = usePersistedState<BankAccount[]>('bankAccounts', []);
  const [clientNotes, setClientNotes] = usePersistedState<ClientNote[]>('clientNotes', []);
  const [clientDocuments, setClientDocuments] = usePersistedState<ClientDocument[]>('clientDocuments', []);
  const [auditLogs, setAuditLogs] = usePersistedState<AuditLog[]>('auditLogs', []);

  // Auth & System State with Persistence
  const [users, setUsers] = usePersistedState<User[]>('users', initialUsers);
  const [roles, setRoles] = usePersistedState<Role[]>('roles', initialRoles);
  const [companySettings, setCompanySettings] = usePersistedState<CompanySettings>('companySettings', initialCompanySettings);

  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('currentUser');
    return saved ? JSON.parse(saved) : null;
  });

  const logAction = (action: string, details: string) => {
      const newLog: AuditLog = {
          id: `LOG-${Date.now()}`,
          userId: currentUser?.id || 'system',
          userName: currentUser?.name || 'System',
          action,
          details,
          timestamp: new Date().toISOString()
      };
      setAuditLogs(prev => [newLog, ...prev]);
  };

  // --- Auth Actions ---

  const login = (identifier: string, password: string): boolean => {
    const user = users.find(u => 
      (u.email === identifier || u.username === identifier) && u.password === password
    );

    if (user) {
      setCurrentUser(user);
      localStorage.setItem('currentUser', JSON.stringify(user));
      addToast(`Bienvenido de nuevo, ${user.name}`, 'success');
      return true;
    }
    addToast("Credenciales inválidas", 'error');
    return false;
  };

  const logout = () => {
    logAction('Logout', 'Cierre de sesión');
    setCurrentUser(null);
    localStorage.removeItem('currentUser');
    addToast("Sesión cerrada correctamente", 'info');
  };

  const registerUser = (user: User) => {
    setUsers(prev => [...prev, user]);
    logAction('Register User', `Nuevo usuario registrado: ${user.name}`);
    addToast("Usuario registrado exitosamente", 'success');
  };

  const updateUser = (updatedUser: User) => {
    setUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
    if (currentUser && currentUser.id === updatedUser.id) {
        setCurrentUser(updatedUser);
        localStorage.setItem('currentUser', JSON.stringify(updatedUser));
    }
    logAction('Update User', `Perfil actualizado: ${updatedUser.name}`);
    addToast("Perfil actualizado", 'success');
  };

  const updateCompanySettings = (settings: CompanySettings) => {
    setCompanySettings(settings);
    logAction('Update Settings', 'Actualización de configuración de empresa');
    addToast("Configuración guardada", 'success');
  };

  const addRole = (role: Role) => {
    setRoles(prev => [...prev, role]);
    logAction('Add Role', `Creación de rol: ${role.name}`);
    addToast("Rol creado", 'success');
  };

  const deleteRole = (id: string) => {
    setRoles(prev => prev.filter(r => r.id !== id));
    logAction('Delete Role', `Eliminación de rol ID: ${id}`);
    addToast("Rol eliminado", 'info');
  };

  // --- Domain Actions ---

  const addClient = (client: Client) => {
    setClients(prev => [client, ...prev]);
    logAction('Create Client', `Cliente creado: ${client.name} - ${client.cedula}`);
    addToast("Cliente registrado", 'success');
  };

  const updateClient = (updatedClient: Client) => {
    setClients(prev => prev.map(c => c.id === updatedClient.id ? updatedClient : c));
    logAction('Update Client', `Cliente actualizado: ${updatedClient.name}`);
    addToast("Cliente actualizado", 'success');
  };

  const addEmployee = (employee: Employee) => {
      setEmployees(prev => [...prev, employee]);
      logAction('Add Employee', `Empleado registrado: ${employee.name}`);
      addToast("Empleado registrado", 'success');
  };

  const deleteEmployee = (id: string) => {
      setEmployees(prev => prev.filter(e => e.id !== id));
      logAction('Delete Employee', `Empleado eliminado ID: ${id}`);
      addToast("Empleado eliminado", 'info');
  };

  const addLoanRequest = (request: Omit<LoanRequest, 'id' | 'status' | 'requestDate'>) => {
      const newRequest: LoanRequest = {
          ...request,
          id: `REQ-${Math.floor(1000 + Math.random() * 9000)}`,
          status: 'Pendiente',
          requestDate: new Date().toISOString().split('T')[0]
      };
      setLoanRequests(prev => [newRequest, ...prev]);
      logAction('Create Request', `Solicitud creada para ${request.clientName}`);
      addToast("Solicitud de préstamo creada", 'success');
  };

  const deleteLoanRequest = (requestId: string) => {
      setLoanRequests(prev => prev.filter(r => r.id !== requestId));
      logAction('Remove Request', `Solicitud eliminada/procesada: ${requestId}`);
  };

  const createLoan = (loanData: Omit<Loan, 'id' | 'status' | 'remainingBalance' | 'totalToPay'>) => {
    // ... logic remains same ...
    let finalPrincipal = loanData.amount;
    const closingCost = loanData.closingCost || 0;
    if (loanData.closingCostMode === 'Financiado') finalPrincipal += closingCost;

    let totalToPay = 0;
    let initialBalance = 0;

    if (loanData.loanType === 'Amortizado') {
        const totalInterest = finalPrincipal * (loanData.interestRate / 100);
        totalToPay = finalPrincipal + totalInterest;
        initialBalance = totalToPay;
    } else {
        totalToPay = finalPrincipal;
        initialBalance = finalPrincipal;
    }

    let nextPaymentDate = loanData.nextPaymentDate;
    if (loanData.frequency === 'Mensual' && loanData.paymentDay && !nextPaymentDate) {
         const d = new Date();
         if (d.getDate() >= loanData.paymentDay) {
             d.setMonth(d.getMonth() + 1);
         }
         d.setDate(loanData.paymentDay);
         nextPaymentDate = d.toISOString().split('T')[0];
    } else if (!nextPaymentDate) {
         const d = new Date();
         d.setDate(d.getDate() + 7);
         nextPaymentDate = d.toISOString().split('T')[0];
    }

    const newLoan: Loan = {
      ...loanData,
      amount: finalPrincipal, 
      id: `LN-${Math.floor(1000 + Math.random() * 9000)}`,
      status: LoanStatus.ACTIVE,
      totalToPay,
      remainingBalance: initialBalance,
      nextPaymentDate
    };

    setLoans(prev => [newLoan, ...prev]);

    let disbursementAmount = loanData.amount;
    if (loanData.closingCostMode === 'Descontado') {
        disbursementAmount = loanData.amount - closingCost;
    }

    const transactionId = `TRX-${Math.floor(Date.now() / 1000)}`;
    const disbursalTransaction: Transaction = {
      id: transactionId,
      type: 'Gasto',
      category: 'Desembolso',
      amount: disbursementAmount,
      date: new Date().toISOString().split('T')[0],
      description: `Desembolso ${newLoan.loanType} para ${loanData.clientName}`,
      referenceId: newLoan.id
    };
    setTransactions(prev => [disbursalTransaction, ...prev]);

    if (loanData.closingCostMode === 'Externo' && closingCost > 0) {
        const feeTransaction: Transaction = {
            id: `TRX-FEE-${Math.floor(Date.now() / 1000)}`,
            type: 'Ingreso',
            category: 'Cierre',
            amount: closingCost,
            date: new Date().toISOString().split('T')[0],
            description: `Cobro Gastos de Cierre - ${loanData.clientName}`,
            referenceId: newLoan.id
        };
        setTransactions(prev => [feeTransaction, ...prev]);
    }

    // Auto contract
    const contractDoc: ClientDocument = {
        id: `DOC-CONT-${Date.now()}`,
        clientId: loanData.clientId,
        title: `Contrato Préstamo ${newLoan.id}`,
        type: 'Contrato',
        fileUrl: '', 
        fileType: 'application/pdf',
        uploadDate: new Date().toISOString().split('T')[0]
    };
    setClientDocuments(prev => [contractDoc, ...prev]);

    logAction('Create Loan', `Préstamo ${newLoan.id} desembolsado.`);
    addToast(`Préstamo ${newLoan.id} desembolsado correctamente`, 'success');
  };

  const refinanceLoan = (oldLoanId: string, newLoanData: Omit<Loan, 'id' | 'status' | 'remainingBalance' | 'totalToPay'>) => {
    let oldBalance = 0;
    setLoans(prev => prev.map(l => {
        if (l.id === oldLoanId) {
            oldBalance = l.remainingBalance;
            return { ...l, remainingBalance: 0, status: LoanStatus.PAID };
        }
        return l;
    }));

    createLoan(newLoanData);

    const transaction: Transaction = {
        id: `TRX-REF-${Math.floor(Date.now() / 1000)}`,
        type: 'Ingreso',
        category: 'Pago Préstamo',
        amount: oldBalance,
        date: new Date().toISOString().split('T')[0],
        description: `Refinanciamiento: Cancelación Saldo ${oldLoanId}`,
        referenceId: oldLoanId
    };
    setTransactions(prev => [transaction, ...prev]);
    logAction('Refinance Loan', `Refinanciamiento de ${oldLoanId}.`);
    addToast("Préstamo refinanciado", 'success');
  };

  const registerPayment = (loanId: string, amount: number, note: string) => {
    setLoans(prevLoans => prevLoans.map(loan => {
      if (loan.id === loanId) {
        const newBalance = Math.max(0, loan.remainingBalance - amount);
        const newStatus = newBalance === 0 ? LoanStatus.PAID : LoanStatus.ACTIVE;
        return { ...loan, remainingBalance: newBalance, status: newStatus };
      }
      return loan;
    }));

    const loan = loans.find(l => l.id === loanId);
    const transaction: Transaction = {
      id: `TRX-${Math.floor(Date.now() / 1000)}`,
      type: 'Ingreso',
      category: 'Pago Préstamo',
      amount: amount,
      date: new Date().toISOString().split('T')[0],
      description: `Pago: ${note} - ${loan?.clientName}`,
      referenceId: loanId
    };
    setTransactions(prev => [transaction, ...prev]);
    logAction('Register Payment', `Pago registrado: $${amount} para préstamo ${loanId}`);
    addToast(`Pago de $${amount} registrado`, 'success');
  };

  const addBankAccount = (account: BankAccount) => {
    setBankAccounts(prev => [...prev, account]);
    logAction('Add Bank', `Cuenta bancaria agregada para cliente ${account.clientId}`);
    addToast("Cuenta bancaria agregada", 'success');
  };

  const removeBankAccount = (id: string) => {
    setBankAccounts(prev => prev.filter(b => b.id !== id));
    logAction('Remove Bank', `Cuenta bancaria eliminada ID: ${id}`);
    addToast("Cuenta eliminada", 'info');
  };

  const addClientNote = (note: ClientNote) => {
    setClientNotes(prev => [note, ...prev]);
    logAction('Add Note', `Nota agregada a cliente ${note.clientId}`);
    addToast("Nota guardada", 'success');
  };

  const addClientDocument = (doc: ClientDocument) => {
      setClientDocuments(prev => [doc, ...prev]);
      logAction('Upload Document', `Documento subido para cliente ${doc.clientId}: ${doc.title}`);
      addToast("Documento subido", 'success');
  };

  const removeClientDocument = (id: string) => {
      setClientDocuments(prev => prev.filter(d => d.id !== id));
      logAction('Delete Document', `Documento eliminado ID: ${id}`);
      addToast("Documento eliminado", 'info');
  };

  const getFinancialStats = () => {
    const today = new Date().toISOString().split('T')[0];

    const balance = transactions.reduce((acc, curr) => {
      return curr.type === 'Ingreso' ? acc + curr.amount : acc - curr.amount;
    }, 0);

    const incomeToday = transactions
      .filter(t => t.date === today && t.type === 'Ingreso')
      .reduce((sum, t) => sum + t.amount, 0);

    const expenseToday = transactions
      .filter(t => t.date === today && t.type === 'Gasto')
      .reduce((sum, t) => sum + t.amount, 0);

    return { balance, incomeToday, expenseToday };
  };

  return (
    <StoreContext.Provider value={{ 
      clients, loans, loanRequests, employees, transactions, bankAccounts, clientNotes, clientDocuments, auditLogs,
      currentUser, users, roles, companySettings,
      login, logout, registerUser, updateUser, updateCompanySettings, addRole, deleteRole,
      addClient, updateClient, 
      addEmployee, deleteEmployee,
      addLoanRequest, deleteLoanRequest, createLoan, 
      refinanceLoan, registerPayment, 
      addBankAccount, removeBankAccount, addClientNote,
      addClientDocument, removeClientDocument,
      getFinancialStats 
    }}>
      {children}
    </StoreContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(StoreContext);
  if (context === undefined) {
    throw new Error('useStore must be used within a StoreProvider');
  }
  return context;
};

